import { Container, Graphics } from 'pixi.js';
import type { ActorSpawnDef, ValueAtom } from '../types';

export interface SwitchTimerParams {
  timer: number;
}

const DEFAULT_TIMER = 0;

export class SwitchTimer {
  readonly view = new Container();
  readonly params: SwitchTimerParams;
  readonly targetLabel: string;
  private remainingSeconds: number;
  private fired = false;

  constructor(readonly spawn: ActorSpawnDef) {
    this.params = parseSwitchTimerParamsFromSpawn(spawn);
    // Recovered-data: SwitchTimer broadcasts command 9 after its immediate
    // seconds countdown. The native target resolver removes the actor prefix.
    this.targetLabel = spawn.label.replace(/^SwitchTimer/, '');
    this.remainingSeconds = Math.max(0, this.params.timer);
    this.view.x = spawn.x;
    this.view.y = spawn.y;

    const g = new Graphics();
    g.beginFill(0xf97316, 0.26);
    g.lineStyle(2, 0xfb923c, 0.9);
    g.drawRoundedRect(-18, -8, 36, 16, 4);
    g.endFill();
    g.beginFill(0xffffff, 0.5);
    g.drawRect(-11, -2, 22, 4);
    g.endFill();
    this.view.addChild(g);
  }

  update(dtSeconds: number): boolean {
    if (this.fired) return false;
    this.remainingSeconds -= Math.max(0, dtSeconds);
    if (this.remainingSeconds > 1e-9) return false;
    this.fired = true;
    return true;
  }
}

export function parseSwitchTimerParamsFromSpawn(spawn: ActorSpawnDef): SwitchTimerParams {
  return {
    timer: parseSwitchTimerAfterCoordinatePair(spawn.raw, spawn.x, spawn.y) ?? DEFAULT_TIMER,
  };
}

export function parseSwitchTimerAfterCoordinatePair(
  raw: readonly ValueAtom[],
  x: number,
  y: number,
): number | undefined {
  for (let index = 0; index <= raw.length - 3; index += 1) {
    if (raw[index] !== x || raw[index + 1] !== y) continue;

    const timer = raw[index + 2];
    if (typeof timer === 'number' && Number.isFinite(timer)) {
      return Math.trunc(timer);
    }
  }

  return undefined;
}
