import { Container, Graphics } from 'pixi.js';
import type { ActorSpawnDef, Rect, ValueAtom } from '../types';

export interface DarknessRectParams {
  width: number;
  height: number;
}

const DEFAULT_DARKNESS_RECT_WIDTH = 64;
const DEFAULT_DARKNESS_RECT_HEIGHT = 64;

export class DarknessRect {
  readonly view = new Container();
  readonly rect: Rect;
  readonly params: DarknessRectParams;

  constructor(readonly spawn: ActorSpawnDef) {
    this.params = parseDarknessRectParamsFromSpawn(spawn);
    this.rect = {
      x: spawn.x - this.params.width / 2,
      y: spawn.y - this.params.height / 2,
      width: this.params.width,
      height: this.params.height,
    };
    this.view.x = spawn.x;
    this.view.y = spawn.y;
    this.view.alpha = 0.72;

    const g = new Graphics();
    g.beginFill(0x050505, 0.82);
    g.lineStyle(1, 0x1e293b, 0.72);
    g.drawRect(-this.params.width / 2, -this.params.height / 2, this.params.width, this.params.height);
    g.endFill();
    this.view.addChild(g);
  }
}

export function parseDarknessRectParamsFromSpawn(spawn: ActorSpawnDef): DarknessRectParams {
  return parseDarknessRectParamsAfterCoordinatePair(spawn.raw, spawn.x, spawn.y) ?? {
    width: DEFAULT_DARKNESS_RECT_WIDTH,
    height: DEFAULT_DARKNESS_RECT_HEIGHT,
  };
}

export function parseDarknessRectParamsAfterCoordinatePair(
  raw: readonly ValueAtom[],
  x: number,
  y: number,
): DarknessRectParams | undefined {
  for (let index = 0; index <= raw.length - 4; index += 1) {
    if (raw[index] !== x || raw[index + 1] !== y) continue;

    const width = raw[index + 2];
    const height = raw[index + 3];
    if (isPositiveFiniteNumber(width) && isPositiveFiniteNumber(height)) {
      return { width, height };
    }
  }

  return undefined;
}

function isPositiveFiniteNumber(value: ValueAtom | undefined): value is number {
  return typeof value === 'number' && Number.isFinite(value) && value > 0;
}
