import { Container, Graphics } from 'pixi.js';
import type { ActorSpawnDef, ValueAtom } from '../types';

export interface ColorBoxParams {
  colorIndex: number;
  width: number;
  height: number;
  mode?: number;
}

export const COLOR_BOX_FALLBACK_SIZE = 32;

const COLOR_BOX_PALETTE = [0x5ec8ff, 0xffd166, 0x9be564, 0xff7aa2, 0xc084fc, 0xff9f1c];

export class ColorBox {
  readonly view = new Container();
  readonly params?: ColorBoxParams;

  constructor(readonly spawn: ActorSpawnDef) {
    this.params = parseColorBoxParamsFromSpawn(spawn);
    this.view.x = spawn.x;
    this.view.y = spawn.y;

    const width = this.params?.width ?? COLOR_BOX_FALLBACK_SIZE;
    const height = this.params?.height ?? COLOR_BOX_FALLBACK_SIZE;
    const color = this.params ? COLOR_BOX_PALETTE[Math.abs(Math.trunc(this.params.colorIndex)) % COLOR_BOX_PALETTE.length] : 0x607080;
    const g = new Graphics();
    g.beginFill(color, 0.58);
    g.lineStyle(2, this.params ? 0xffffff : 0x607080, 0.85);
    g.drawRoundedRect(-width / 2, -height / 2, width, height, Math.max(3, Math.min(width, height) * 0.12));
    g.endFill();
    g.beginFill(0xffffff, 0.32);
    g.drawRect(-width / 2 + 4, -height / 2 + 4, Math.max(0, width - 8), Math.min(5, Math.max(0, height - 8)));
    g.endFill();
    this.view.addChild(g);
  }
}

export function parseColorBoxParamsFromSpawn(spawn: ActorSpawnDef): ColorBoxParams | undefined {
  // Recovered-data: native ForceColorBox consumes param0 color + param1/param2 extents and ignores param3.
  return parseColorBoxParamsAfterCoordinatePair(spawn.raw, spawn.x, spawn.y, {
    includeMode: spawn.actorName !== 'ForceColorBox',
  });
}

export function parseColorBoxParamsAfterCoordinatePair(
  raw: readonly ValueAtom[],
  x: number,
  y: number,
  options: { includeMode?: boolean } = {},
): ColorBoxParams | undefined {
  let fallbackParams: ColorBoxParams | undefined;
  const includeMode = options.includeMode ?? true;

  for (let index = 0; index <= raw.length - 2; index++) {
    if (raw[index] !== x || raw[index + 1] !== y) continue;

    const colorIndex = raw[index + 2];
    const width = raw[index + 3];
    const height = raw[index + 4];
    const mode = raw[index + 5];

    const params = {
      colorIndex: isFiniteNumber(colorIndex) ? colorIndex : 0,
      width: positiveOrDefault(width, COLOR_BOX_FALLBACK_SIZE),
      height: positiveOrDefault(height, COLOR_BOX_FALLBACK_SIZE),
      ...(includeMode && isFiniteNumber(mode) ? { mode } : {}),
    };
    if (isFiniteNumber(colorIndex) || colorIndex === undefined) {
      return params;
    }

    fallbackParams = params;
  }

  return fallbackParams;
}

function isFiniteNumber(value: ValueAtom | undefined): value is number {
  return typeof value === 'number' && Number.isFinite(value);
}

function positiveOrDefault(value: ValueAtom | undefined, fallback: number): number {
  return isFiniteNumber(value) && value > 0 ? value : fallback;
}
