import { Container, Text, TextStyle } from 'pixi.js';
import type { ActorSpawnDef } from '../types';

const FLOAT32_EPSILON = 1.1920928955078125e-7;

export interface DeadTimerParams {
  baseSeconds: number;
  perPlayerSeconds: number;
}

export class DeadTimer {
  readonly view = new Container();
  readonly params: DeadTimerParams;
  private readonly label: Text;
  readonly timeUpLabel: Text;
  readonly durationSeconds: number;
  remainingSeconds: number;
  timeUp = false;
  private expired = false;

  constructor(readonly spawn: ActorSpawnDef, activePlayerCount = 1) {
    this.params = parseDeadTimerParamsFromSpawn(spawn);
    this.durationSeconds = deadTimerDurationSeconds(this.params, activePlayerCount);
    this.remainingSeconds = this.durationSeconds;
    this.view.x = spawn.x;
    this.view.y = spawn.y;

    this.label = new Text(formatDeadTimerLabel(this.remainingSeconds), new TextStyle({
      fill: 0xffffff,
      fontSize: 32,
      fontFamily: 'monospace',
      fontWeight: '700',
      align: 'center',
      stroke: 0x000000,
      strokeThickness: 2,
    }));
    this.label.anchor.set(0.5);
    this.view.addChild(this.label);

    this.timeUpLabel = new Text('TIME UP', new TextStyle({
      fill: 0xffffff,
      fontSize: 32,
      fontFamily: 'monospace',
      fontWeight: '700',
      align: 'center',
      stroke: 0x000000,
      strokeThickness: 2,
    }));
    this.timeUpLabel.anchor.set(0.5);
    this.timeUpLabel.y = 40;
    this.timeUpLabel.visible = false;
    this.view.addChild(this.timeUpLabel);
  }

  addSeconds(payloadSeconds: number): void {
    if (this.expired || !Number.isFinite(payloadSeconds)) return;
    const integerSeconds = Math.trunc(payloadSeconds);
    if (integerSeconds <= 0) return;
    this.remainingSeconds = Math.fround(Math.ceil(Math.fround(
      Math.fround(this.remainingSeconds) + Math.fround(integerSeconds),
    )));
    this.refreshLabel();
  }

  tick(dt: number): boolean {
    if (this.expired) return false;
    if (this.remainingSeconds > 0) {
      this.remainingSeconds = Math.max(
        0,
        Math.fround(Math.fround(this.remainingSeconds) - Math.fround(Math.max(0, dt))),
      );
    }
    if (this.remainingSeconds <= FLOAT32_EPSILON) {
      this.remainingSeconds = 0;
      this.expired = true;
      this.timeUp = true;
    }
    this.refreshLabel();
    return this.expired;
  }

  private refreshLabel(): void {
    this.label.text = formatDeadTimerLabel(this.remainingSeconds);
    this.timeUpLabel.visible = this.timeUp;
  }
}

export function formatDeadTimerLabel(remainingSeconds: number): string {
  const totalSeconds = Number.isFinite(remainingSeconds)
    ? Math.max(0, Math.ceil(remainingSeconds))
    : 0;
  return `${pad2(Math.floor(totalSeconds / 60))}:${pad2(totalSeconds % 60)}`;
}

export function parseDeadTimerParamsFromSpawn(spawn: ActorSpawnDef): DeadTimerParams {
  const coordinateIndex = findCoordinatePairIndex(spawn.raw, spawn.x, spawn.y);
  return {
    baseSeconds: finiteNumberAt(spawn.raw, coordinateIndex + 2),
    perPlayerSeconds: finiteNumberAt(spawn.raw, coordinateIndex + 3),
  };
}

export function deadTimerDurationSeconds(params: DeadTimerParams, activePlayerCount: number): number {
  const playerCount = Math.max(1, Math.trunc(activePlayerCount));
  const durationSeconds = Math.fround(
    Math.fround(params.baseSeconds)
      + Math.fround(playerCount * Math.fround(params.perPlayerSeconds)),
  );
  return durationSeconds > 0 ? durationSeconds : 0;
}

function findCoordinatePairIndex(raw: readonly unknown[], x: number, y: number): number {
  for (let i = 0; i < raw.length - 2; i += 1) {
    if (raw[i] === x && raw[i + 1] === y) {
      return i;
    }
  }
  return raw.length;
}

function finiteNumberAt(raw: readonly unknown[], index: number): number {
  const value = raw[index];
  return typeof value === 'number' && Number.isFinite(value) ? Math.fround(value) : 0;
}

function pad2(value: number): string {
  return String(value).padStart(2, '0');
}
