import { Container, Graphics } from 'pixi.js';
import type { ActorSpawnDef, ValueAtom } from '../types';

export const NORMAL_BOX_FALLBACK_SIZE = 48;
export const NORMAL_BOX_NATIVE_SIZE = 96;

const NATIVE_GENERIC_BOX_DIMENSIONS: Record<string, { width: number; height: number }> = {
  TallBox: { width: 80, height: 703 },
  BigBox: { width: 96, height: 128 },
  NormalBox: { width: NORMAL_BOX_NATIVE_SIZE, height: NORMAL_BOX_NATIVE_SIZE },
  Roulette: { width: 44, height: 56 },
};

export interface NormalBoxParams {
  width?: number;
  height?: number;
  /** Compatibility alias for existing square-box callers; for rectangular boxes this is height. */
  size: number;
}

export class NormalBox {
  readonly view = new Container();
  readonly params?: NormalBoxParams;

  constructor(readonly spawn: ActorSpawnDef) {
    this.params = parseNormalBoxParamsFromSpawn(spawn);
    this.view.x = spawn.x;
    this.view.y = spawn.y;

    const width = this.params?.width ?? this.params?.size ?? NORMAL_BOX_FALLBACK_SIZE;
    const height = this.params?.height ?? this.params?.size ?? NORMAL_BOX_FALLBACK_SIZE;
    const halfWidth = width / 2;
    const halfHeight = height / 2;
    const g = new Graphics();
    g.beginFill(0x8f8f8f, 0.68);
    g.lineStyle(3, this.params ? 0xd8d8d8 : 0x6c6c6c, 0.95);
    g.drawRoundedRect(-halfWidth, -halfHeight, width, height, Math.max(3, Math.min(width, height) * 0.12));
    g.endFill();
    g.beginFill(0x4f4f4f, 0.42);
    g.drawRect(-halfWidth + 5, -2, Math.max(0, width - 10), 4);
    g.drawRect(-2, -halfHeight + 5, 4, Math.max(0, height - 10));
    g.endFill();
    this.view.addChild(g);
  }
}

export function parseNormalBoxParamsFromSpawn(spawn: ActorSpawnDef): NormalBoxParams | undefined {
  const nativeDimensions = NATIVE_GENERIC_BOX_DIMENSIONS[spawn.actorName];
  if (nativeDimensions) return dimensionsToParams(nativeDimensions);
  return parseNormalBoxParamsAfterCoordinatePair(spawn.raw, spawn.x, spawn.y);
}

export function parseNormalBoxParamsAfterCoordinatePair(
  raw: readonly ValueAtom[],
  x: number,
  y: number,
): NormalBoxParams | undefined {
  for (let index = 0; index <= raw.length - 3; index++) {
    if (raw[index] !== x || raw[index + 1] !== y) continue;

    const size = raw[index + 2];
    if (typeof size === "number" && Number.isFinite(size) && size > 0) {
      return { size };
    }
  }

  return undefined;
}

function dimensionsToParams(dimensions: { width: number; height: number }): NormalBoxParams {
  return { ...dimensions, size: dimensions.height };
}
