import { Container, Graphics } from 'pixi.js';
import type { ActorSpawnDef, Rect } from '../types';

export class CheckPoint {
  readonly view = new Container();
  readonly rect: Rect;
  activated = false;

  constructor(readonly spawn: ActorSpawnDef) {
    this.view.x = spawn.x;
    this.view.y = spawn.y;
    this.rect = {
      x: spawn.x - 4,
      y: spawn.y - 28,
      width: 34,
      height: 40,
    };

    const g = new Graphics();
    g.beginFill(0xffd166, 0.72);
    g.lineStyle(2, 0xffffff, 0.9);
    g.drawRect(-4, -28, 8, 40);
    g.endFill();
    g.beginFill(0x66e0ff, 0.76);
    g.lineStyle(2, 0xffffff, 0.9);
    g.drawRoundedRect(4, -28, 26, 18, 3);
    g.endFill();
    this.view.addChild(g);
    this.view.alpha = 0.74;
  }

  activate(): void {
    this.activated = true;
    this.view.alpha = 1;
  }
}
