import { Container, Graphics } from 'pixi.js';
import type { ActorSpawnDef, Rect, ValueAtom } from '../types';

export const THUNDER_SIZE = 24;
export const THUNDER_STRIP_LENGTH = 2400;
export const THUNDER_STRIP_THICKNESS = 4;
export const THUNDER_DRAW_TOGGLE_SECONDS = 0.1;

// Recovered Thunder semantics: native hit fixtures are 4px strips extending 2400px
// from the spawn anchor in the parsed direction. The damaging strip uses a live
// active length, shortened by blocker contacts unless param1 sets native bit 0x2.
export type ThunderDirection = 'DIR_LEFT' | 'DIR_RIGHT' | 'DIR_UP' | 'DIR_DOWN' | 'UNKNOWN';

export interface ThunderParams {
  label: string;
  direction: ThunderDirection;
  numericParams: number[];
  auxiliaryBodyActive: boolean;
  auxiliaryBodyType: 2 | 3;
}

export class Thunder {
  readonly view = new Container();
  readonly rect: Rect;
  readonly direction: ThunderDirection;
  readonly blockShorteningDisabled: boolean;
  readonly auxiliaryBodyActive: boolean;
  readonly auxiliaryBodyType: 2 | 3;
  animationFrame = 0;
  private readonly animationFrames: Graphics[] = [];
  private animationAccumulator = 0;
  private readonly currentOverlapPlayerIndexes = new Set<number>();
  private readonly previousOverlapPlayerIndexes = new Set<number>();
  private readonly previousPreviousOverlapPlayerIndexes = new Set<number>();

  constructor(readonly spawn: ActorSpawnDef) {
    this.rect = getThunderRect(spawn);
    this.direction = parseThunderDirectionFromSpawn(spawn);
    this.blockShorteningDisabled = thunderNativeParamIsNonZero(spawn, 1);
    this.auxiliaryBodyActive = thunderNativeParamIsNonZero(spawn, 2);
    this.auxiliaryBodyType = thunderAuxiliaryBodyType(spawn);
    this.view.x = spawn.x;
    this.view.y = spawn.y;

    this.animationFrames = [
      createThunderFrame(this.direction, 0),
      createThunderFrame(this.direction, 1),
    ];
    this.view.addChild(...this.animationFrames);
    this.applyAnimationFrame();
  }

  update(dt: number): void {
    // Recovered-data: raw slot 25 0x7ff72bb4d600 shifts the whole actor
    // bitfields +0x4e0 -> +0x4e4 -> +0x4e8 once per Thunder frame.
    this.shiftOverlapLatch();
    if (dt <= 0) return;
    this.animationAccumulator += dt;
    if (this.animationAccumulator <= THUNDER_DRAW_TOGGLE_SECONDS) return;

    this.animationAccumulator = 0;
    this.animationFrame = this.animationFrame === 0 ? 1 : 0;
    this.applyAnimationFrame();
  }

  shouldRespawnPlayer(playerIndex: number, playerRect: Rect, blockerRects: readonly Rect[] = []): boolean {
    const overlaps = shouldRespawnPlayerForThunder(playerRect, this.activeRectForBlockers(blockerRects));
    const wasOverlapping = this.previousOverlapPlayerIndexes.has(playerIndex);
    // FUN_7ff72bb4d850 tests the entire +0x4e8 bitfield for zero, not only
    // the current player's bit. An older overlap from any player suppresses it.
    const previousPreviousOverlapIsClear = this.previousPreviousOverlapPlayerIndexes.size === 0;
    const shouldRespawn = overlaps && wasOverlapping && previousPreviousOverlapIsClear;

    if (overlaps) {
      this.currentOverlapPlayerIndexes.add(playerIndex);
    } else {
      this.currentOverlapPlayerIndexes.delete(playerIndex);
    }
    return shouldRespawn;
  }

  activeRectForBlockers(blockerRects: readonly Rect[]): Rect {
    if (this.blockShorteningDisabled || blockerRects.length === 0) return { ...this.rect };
    return getThunderRectForLength(this.spawn, this.direction, this.activeLengthForBlockers(blockerRects));
  }

  private shiftOverlapLatch(): void {
    this.previousPreviousOverlapPlayerIndexes.clear();
    for (const playerIndex of this.previousOverlapPlayerIndexes) {
      this.previousPreviousOverlapPlayerIndexes.add(playerIndex);
    }

    this.previousOverlapPlayerIndexes.clear();
    for (const playerIndex of this.currentOverlapPlayerIndexes) {
      this.previousOverlapPlayerIndexes.add(playerIndex);
    }
    this.currentOverlapPlayerIndexes.clear();
  }

  private activeLengthForBlockers(blockerRects: readonly Rect[]): number {
    let activeLength = THUNDER_STRIP_LENGTH;

    for (const blockerRect of blockerRects) {
      const currentActiveRect = getThunderRectForLength(this.spawn, this.direction, activeLength);
      if (!rectsOverlap(currentActiveRect, blockerRect)) continue;

      const shortenedLength = thunderLengthToBlocker(this.spawn, this.direction, blockerRect);
      if (shortenedLength === undefined) continue;
      activeLength = Math.min(activeLength, Math.max(0, Math.min(THUNDER_STRIP_LENGTH, shortenedLength)));
    }

    return activeLength;
  }

  private applyAnimationFrame(): void {
    for (let index = 0; index < this.animationFrames.length; index += 1) {
      this.animationFrames[index].visible = index === this.animationFrame;
    }
  }
}

export function getThunderRect(spawn: ActorSpawnDef): Rect {
  return getThunderRectForLength(spawn, parseThunderDirectionFromSpawn(spawn), THUNDER_STRIP_LENGTH);
}

function getThunderRectForLength(spawn: ActorSpawnDef, direction: ThunderDirection, length: number): Rect {
  const halfThickness = THUNDER_STRIP_THICKNESS / 2;

  switch (direction) {
    case 'DIR_UP':
      return {
        x: spawn.x - halfThickness,
        y: spawn.y - length,
        width: THUNDER_STRIP_THICKNESS,
        height: length,
      };
    case 'DIR_DOWN':
      return {
        x: spawn.x - halfThickness,
        y: spawn.y,
        width: THUNDER_STRIP_THICKNESS,
        height: length,
      };
    case 'DIR_LEFT':
      return {
        x: spawn.x - length,
        y: spawn.y - halfThickness,
        width: length,
        height: THUNDER_STRIP_THICKNESS,
      };
    case 'DIR_RIGHT':
      return {
        x: spawn.x,
        y: spawn.y - halfThickness,
        width: length,
        height: THUNDER_STRIP_THICKNESS,
      };
    default:
      return {
        x: spawn.x - THUNDER_SIZE / 2,
        y: spawn.y - THUNDER_SIZE / 2,
        width: THUNDER_SIZE,
        height: THUNDER_SIZE,
      };
  }
}

export function parseThunderDirectionFromSpawn(spawn: ActorSpawnDef): ThunderDirection {
  return parseThunderDirectionAfterCoordinatePair(spawn.raw, spawn.x, spawn.y);
}

export function parseThunderParamsFromSpawn(spawn: ActorSpawnDef): ThunderParams {
  const direction = parseThunderDirectionFromSpawn(spawn);
  const numericParams = parseThunderNumericParamsAfterCoordinatePair(spawn.raw, spawn.x, spawn.y);

  return {
    label: parseThunderLabel(spawn),
    direction,
    numericParams,
    auxiliaryBodyActive: thunderNativeParamIsNonZero(spawn, 2),
    auxiliaryBodyType: thunderAuxiliaryBodyType(spawn),
  };
}

export function parseThunderDirectionAfterCoordinatePair(
  raw: readonly ValueAtom[],
  x: number,
  y: number,
): ThunderDirection {
  const actorNameIndex = raw.findIndex((value) => value === 'Thunder');
  const firstSpawnCoordinateIndex = actorNameIndex >= 0 ? actorNameIndex + 2 : 0;

  for (let index = firstSpawnCoordinateIndex; index <= raw.length - 3; index++) {
    if (raw[index] !== x || raw[index + 1] !== y) continue;
    return normalizeThunderDirection(raw[index + 2]);
  }

  return 'UNKNOWN';
}

export function shouldRespawnPlayerForThunder(playerRect: Rect, thunderRect: Rect): boolean {
  return rectsOverlap(playerRect, thunderRect);
}

function parseThunderLabel(spawn: ActorSpawnDef): string {
  const actorNameIndex = spawn.raw.findIndex((value) => value === 'Thunder');
  const rawLabel = actorNameIndex >= 0 ? spawn.raw[actorNameIndex + 1] : undefined;
  return typeof rawLabel === 'string' ? rawLabel : spawn.label;
}

function parseThunderNumericParamsAfterCoordinatePair(
  raw: readonly ValueAtom[],
  x: number,
  y: number,
): number[] {
  const actorNameIndex = raw.findIndex((value) => value === 'Thunder');
  const firstSpawnCoordinateIndex = actorNameIndex >= 0 ? actorNameIndex + 2 : 0;

  for (let index = firstSpawnCoordinateIndex; index <= raw.length - 3; index++) {
    if (raw[index] !== x || raw[index + 1] !== y) continue;
    const firstParamIndex = typeof raw[index + 2] === 'number' ? index + 2 : index + 3;
    return raw.slice(firstParamIndex).filter(isFiniteNumber);
  }

  return [];
}

function thunderLengthToBlocker(
  spawn: ActorSpawnDef,
  direction: ThunderDirection,
  blockerRect: Rect,
): number | undefined {
  switch (direction) {
    case 'DIR_UP':
      return Math.abs((blockerRect.y + blockerRect.height) - spawn.y);
    case 'DIR_DOWN':
      return Math.abs(blockerRect.y - spawn.y);
    case 'DIR_LEFT':
      return Math.abs((blockerRect.x + blockerRect.width) - spawn.x);
    case 'DIR_RIGHT':
      return Math.abs(blockerRect.x - spawn.x);
    default:
      return undefined;
  }
}

function thunderNativeParamIsNonZero(spawn: ActorSpawnDef, paramIndex: number): boolean {
  const value = thunderNativeParam(spawn, paramIndex);
  return value !== undefined && Math.trunc(value) !== 0;
}

function thunderAuxiliaryBodyType(spawn: ActorSpawnDef): 2 | 3 {
  return thunderNativeParamIsNonZero(spawn, 1) ? 2 : 3;
}

function thunderNativeParam(spawn: ActorSpawnDef, paramIndex: number): number | undefined {
  const actorNameIndex = spawn.raw.findIndex((value) => value === 'Thunder');
  const firstSpawnCoordinateIndex = actorNameIndex >= 0 ? actorNameIndex + 2 : 0;

  for (let index = firstSpawnCoordinateIndex; index <= spawn.raw.length - 2; index++) {
    if (spawn.raw[index] !== spawn.x || spawn.raw[index + 1] !== spawn.y) continue;
    const value = spawn.raw[index + 2 + paramIndex];
    return isFiniteNumber(value) ? value : undefined;
  }

  return undefined;
}

function normalizeThunderDirection(value: ValueAtom | undefined): ThunderDirection {
  if (value === 'DIR_LEFT' || value === 'DIR_RIGHT' || value === 'DIR_UP' || value === 'DIR_DOWN') {
    return value;
  }
  if (typeof value === 'number' && Number.isFinite(value)) {
    switch (Math.trunc(value)) {
      case 0:
        return 'DIR_UP';
      case 1:
        return 'DIR_DOWN';
      case 2:
        return 'DIR_LEFT';
      case 3:
        return 'DIR_RIGHT';
      default:
        break;
    }
  }
  return 'UNKNOWN';
}

function createThunderFrame(direction: ThunderDirection, frame: 0 | 1): Graphics {
  const g = new Graphics();
  g.lineStyle(2, frame === 0 ? 0x5b4a00 : 0x8a6b00, 0.95);
  g.beginFill(frame === 0 ? 0xfff176 : 0xffffff, frame === 0 ? 0.9 : 0.82);
  drawThunderBolt(g, direction);
  g.endFill();
  g.beginFill(frame === 0 ? 0xffffff : 0xfff176, 0.85);
  g.drawCircle(0, 0, frame === 0 ? 3 : 4);
  g.endFill();
  return g;
}

function drawThunderBolt(g: Graphics, direction: ThunderDirection): void {
  const points = direction === 'DIR_LEFT' || direction === 'DIR_RIGHT'
    ? [-12, -5, -2, -5, -5, -11, 12, 1, 2, 1, 5, 11]
    : [-5, -12, 1, -12, -1, -3, 8, -3, -5, 12, -1, 2, -9, 2];

  if (direction === 'DIR_LEFT') {
    g.drawPolygon(points.map((point, index) => (index % 2 === 0 ? -point : point)));
    return;
  }

  if (direction === 'DIR_UP') {
    g.drawPolygon(points.map((point, index) => (index % 2 === 1 ? -point : point)));
    return;
  }

  g.drawPolygon(points);
}

function rectsOverlap(a: Rect, b: Rect): boolean {
  return a.x < b.x + b.width
    && a.x + a.width > b.x
    && a.y < b.y + b.height
    && a.y + a.height > b.y;
}

function isFiniteNumber(value: ValueAtom | undefined): value is number {
  return typeof value === 'number' && Number.isFinite(value);
}
