import { getStaticRectDimensions, StaticRect } from './StaticRect';
import type { ActorSpawnDef, Rect, ValueAtom } from '../types';

export interface CollisionConstraintMoveParams {
  targetName: string;
}

export class CollisionConstraintMove extends StaticRect {
  readonly params: CollisionConstraintMoveParams;
  readonly sensorRect: Rect;

  constructor(spawn: ActorSpawnDef) {
    super(spawn);
    this.params = parseCollisionConstraintMoveParamsFromSpawn(spawn);
    const dimensions = getStaticRectDimensions(spawn);
    // Recovered-data: FUN_7ff72bb3ac00 supplies local [0, 0, width, height]
    // to the registered callback body, so the actor position is its top-left.
    // Keep StaticRect's existing presentation geometry separate until draw evidence exists.
    this.sensorRect = { x: spawn.x, y: spawn.y, ...dimensions };
  }
}

export function parseCollisionConstraintMoveParamsFromSpawn(spawn: ActorSpawnDef): CollisionConstraintMoveParams {
  const coordinateIndex = findCoordinatePair(spawn.raw, spawn.x, spawn.y);
  if (coordinateIndex < 0) return { targetName: '' };

  const targetName = spawn.raw
    .slice(coordinateIndex + 4)
    .find(isNonEmptyString);

  return {
    targetName: targetName?.trim() ?? '',
  };
}

function findCoordinatePair(raw: readonly ValueAtom[], x: number, y: number): number {
  for (let index = 0; index <= raw.length - 2; index += 1) {
    if (raw[index] === x && raw[index + 1] === y) return index;
  }

  return -1;
}

function isNonEmptyString(value: ValueAtom): value is string {
  return typeof value === 'string' && value.trim().length > 0;
}
