import { Container, Graphics, Sprite } from 'pixi.js';
import { resolveClosedGateCollision } from './KeyGate';
import { frameTexture, type AtlasFrameName } from '../sprites';
import type { ActorSpawnDef, Rect, ValueAtom, Vector2 } from '../types';

export interface WeightedLiftParams {
  travel: number;
  weight?: number;
  numericFlags: number[];
  width?: number;
  height?: number;
  autoReturn?: number;
}

export interface WeightedLiftCollisionResult {
  blocked: boolean;
  rect: Rect;
  velocity: Vector2;
  grounded: boolean;
}

const LIFT_WIDTH = 64;
const LIFT_HEIGHT = 14;
const UP_DOWN_LIFT_PERIOD_SECONDS = 5;
const TAU = Math.PI * 2;
const LIFT_RECT_CAP_SIZE = 32;
const LIFT_RECT_FRAME_NAMES = [
  ['lift_rect_0_0', 'lift_rect_1_0', 'lift_rect_2_0'],
  ['lift_rect_0_1', 'lift_rect_1_1', 'lift_rect_2_1'],
  ['lift_rect_0_2', 'lift_rect_1_2', 'lift_rect_2_2'],
] as const satisfies readonly (readonly AtlasFrameName[])[];

export interface LiftRectPatch {
  column: number;
  row: number;
  x: number;
  y: number;
  width: number;
  height: number;
}

export function liftRectNineSliceLayout(width: number, height: number): LiftRectPatch[] {
  const farCapWidth = Math.min(LIFT_RECT_CAP_SIZE, width - LIFT_RECT_CAP_SIZE);
  const farCapHeight = Math.min(LIFT_RECT_CAP_SIZE, height - LIFT_RECT_CAP_SIZE);
  const columnWidths = [
    LIFT_RECT_CAP_SIZE,
    width - LIFT_RECT_CAP_SIZE - farCapWidth,
    farCapWidth,
  ];
  const rowHeights = [
    LIFT_RECT_CAP_SIZE,
    height - LIFT_RECT_CAP_SIZE - farCapHeight,
    farCapHeight,
  ];
  const patches: LiftRectPatch[] = [];
  let y = 0;
  for (let row = 0; row < rowHeights.length; row++) {
    let x = 0;
    for (let column = 0; column < columnWidths.length; column++) {
      patches.push({ column, row, x, y, width: columnWidths[column], height: rowHeights[row] });
      x += columnWidths[column];
    }
    y += rowHeights[row];
  }
  return patches;
}

function createLiftRectNineSlice(width: number, height: number): Container[] {
  const patches = liftRectNineSliceLayout(width, height);
  const textures = patches.map((patch) => frameTexture(LIFT_RECT_FRAME_NAMES[patch.row][patch.column]));
  if (textures.every((texture) => texture !== undefined)) {
    return patches.map((patch, index) => {
      const sprite = new Sprite(textures[index]);
      sprite.x = patch.x;
      sprite.y = patch.y;
      sprite.width = patch.width;
      sprite.height = patch.height;
      return sprite;
    });
  }

  const fallback = new Graphics();
  for (const patch of patches) {
    fallback.beginFill((patch.column + patch.row) % 2 === 0 ? 0x4e5966 : 0x657383, 1);
    fallback.drawRect(patch.x, patch.y, patch.width, patch.height);
    fallback.endFill();
  }
  return [fallback];
}


export class WeightedLift {
  readonly view = new Container();
  readonly params?: WeightedLiftParams;
  readonly rect: Rect;
  private upDownLiftPhaseSeconds = 0;
  private baseLiftPhaseSeconds = 0;
  private baseLiftActive = false;

  constructor(readonly spawn: ActorSpawnDef) {
    this.params = parseWeightedLiftParamsFromSpawn(spawn);
    this.baseLiftActive = spawn.actorName === 'Lift' && !this.baseLiftWaitsForSwitch();
    this.view.x = spawn.x;
    this.view.y = spawn.y;
    const isDarknessWeightedLift = spawn.actorName === 'DarknessWeightedLift';
    const liftWidth = this.params?.width ?? LIFT_WIDTH;
    const liftHeight = this.params?.height ?? LIFT_HEIGHT;
    this.rect = {
      x: isDarknessWeightedLift ? spawn.x : spawn.x - liftWidth / 2,
      y: isDarknessWeightedLift ? spawn.y : spawn.y - liftHeight / 2,
      width: liftWidth,
      height: liftHeight,
    };

    const travel = this.params?.travel ?? 0;
    const guideX = spawn.actorName === 'Lift' ? travel : 0;
    const guideY = spawn.actorName === 'Lift' ? (this.params?.weight ?? 0) : travel;
    if (isDarknessWeightedLift) {
      this.view.addChild(...createLiftRectNineSlice(liftWidth, liftHeight));
      return;
    }
    const g = new Graphics();
    g.beginFill(0x8bd3ff, 0.56);
    g.lineStyle(2, this.params ? 0xffffff : 0x607080, 0.86);
    const localX = -liftWidth / 2;
    const localY = -liftHeight / 2;
    g.drawRoundedRect(localX, localY, liftWidth, liftHeight, 4);
    g.endFill();
    g.beginFill(0xffffff, 0.35);
    g.drawRect(localX + 5, localY + 3, Math.max(0, liftWidth - 10), 3);
    g.endFill();
    g.lineStyle(1, 0x8bd3ff, 0.42);
    g.moveTo(0, 0);
    g.lineTo(guideX, guideY);
    this.view.addChild(g);
  }

  update(dt: number): void {
    if (this.spawn.actorName === 'Lift') {
      this.updateBaseLift(dt);
      return;
    }
    if (this.spawn.actorName !== 'UpDownLift' || !this.params || this.params.travel === 0) return;

    this.upDownLiftPhaseSeconds = (this.upDownLiftPhaseSeconds + dt) % UP_DOWN_LIFT_PERIOD_SECONDS;
    const phase = (this.upDownLiftPhaseSeconds / UP_DOWN_LIFT_PERIOD_SECONDS) * TAU;
    const offset = Math.sin(phase) * this.params.travel;

    this.view.y = this.spawn.y + offset;
    this.rect.y = this.view.y - LIFT_HEIGHT / 2;
  }

  activateBaseLift(): void {
    if (this.spawn.actorName !== 'Lift') return;
    this.baseLiftActive = true;
  }

  private updateBaseLift(dt: number): void {
    if (!this.params || !this.baseLiftActive) return;

    this.baseLiftPhaseSeconds += dt * this.baseLiftSpeed();
    const stopPhase = this.baseLiftHalfCycle()
      ? UP_DOWN_LIFT_PERIOD_SECONDS / 2
      : UP_DOWN_LIFT_PERIOD_SECONDS;
    if (this.baseLiftWaitsForSwitch() && this.baseLiftPhaseSeconds >= stopPhase) {
      this.baseLiftPhaseSeconds = 0;
      this.baseLiftActive = false;
      this.applyBaseLiftOffset(0);
      return;
    }
    if (this.baseLiftPhaseSeconds >= UP_DOWN_LIFT_PERIOD_SECONDS) {
      this.baseLiftPhaseSeconds %= UP_DOWN_LIFT_PERIOD_SECONDS;
    }

    let offsetScale = Math.sin((this.baseLiftPhaseSeconds / UP_DOWN_LIFT_PERIOD_SECONDS) * TAU);
    if (this.baseLiftHalfCycle() && offsetScale < 0) offsetScale *= -1;
    this.applyBaseLiftOffset(offsetScale);
  }

  private applyBaseLiftOffset(offsetScale: number): void {
    const motionX = this.params?.travel ?? 0;
    const motionY = this.params?.weight ?? 0;
    const originX = this.params?.numericFlags[0] ?? 0;
    const originY = this.params?.numericFlags[1] ?? 0;

    this.view.x = this.spawn.x + originX + motionX * offsetScale;
    this.view.y = this.spawn.y + originY + motionY * offsetScale;
    this.rect.x = this.view.x - LIFT_WIDTH / 2;
    this.rect.y = this.view.y - LIFT_HEIGHT / 2;
  }

  private baseLiftSpeed(): number {
    const speed = this.params?.numericFlags[2] ?? 1;
    return Number.isFinite(speed) ? speed : 1;
  }

  private baseLiftHalfCycle(): boolean {
    return Math.trunc(this.params?.numericFlags[3] ?? 0) !== 0;
  }

  private baseLiftWaitsForSwitch(): boolean {
    return Math.trunc(this.params?.numericFlags[4] ?? 0) !== 0;
  }
}

export function resolveWeightedLiftPlayerCollision(
  previousPlayerRect: Rect,
  playerRect: Rect,
  playerVelocity: Vector2,
  liftRects: readonly Rect[],
): WeightedLiftCollisionResult {
  return resolveClosedGateCollision(previousPlayerRect, playerRect, playerVelocity, liftRects);
}

export function parseWeightedLiftParamsFromSpawn(spawn: ActorSpawnDef): WeightedLiftParams | undefined {
  if (spawn.actorName === 'DarknessWeightedLift') {
    return parseDarknessWeightedLiftParamsAfterCoordinatePair(spawn.raw, spawn.x, spawn.y);
  }
  return parseWeightedLiftParamsAfterCoordinatePair(
    spawn.raw,
    spawn.x,
    spawn.y,
    spawn.actorName === 'UpDownLift',
  );
}

export function parseDarknessWeightedLiftParamsAfterCoordinatePair(
  raw: readonly ValueAtom[],
  x: number,
  y: number,
): WeightedLiftParams | undefined {
  for (let index = 0; index <= raw.length - 5; index++) {
    if (raw[index] !== x || raw[index + 1] !== y) continue;

    const width = raw[index + 2];
    const height = raw[index + 3];
    const travel = raw[index + 4];
    const rawAutoReturn = raw[index + 5];
    if (!isFiniteNumber(width) || !isFiniteNumber(height) || !isFiniteNumber(travel)) continue;

    return {
      width,
      height,
      travel,
      autoReturn: isFiniteNumber(rawAutoReturn) ? Math.trunc(rawAutoReturn) : 1,
      weight: undefined,
      numericFlags: [],
    };
  }

  return undefined;
}

export function parseWeightedLiftParamsAfterCoordinatePair(
  raw: readonly ValueAtom[],
  x: number,
  y: number,
  allowTravelOnly = false,
): WeightedLiftParams | undefined {
  for (let index = 0; index <= raw.length - 3; index++) {
    if (raw[index] !== x || raw[index + 1] !== y) continue;

    const travel = raw[index + 2];
    const weight = raw[index + 3];
    if (!isFiniteNumber(travel)) continue;
    if (!isFiniteNumber(weight)) {
      if (!allowTravelOnly) continue;

      return {
        travel,
        weight: undefined,
        numericFlags: [],
      };
    }

    return {
      travel,
      weight,
      numericFlags: raw.slice(index + 4).filter(isFiniteNumber),
    };
  }

  return undefined;
}

function isFiniteNumber(value: ValueAtom | undefined): value is number {
  return typeof value === 'number' && Number.isFinite(value);
}
