import { Container, Graphics } from 'pixi.js';
import type { TileMap } from '../TileMap';
import type { ActorSpawnDef, Rect, ValueAtom } from '../types';

export interface StepEnemyParams {
  direction?: number;
}

export const STEP_ENEMY_WIDTH = 20;
export const STEP_ENEMY_HEIGHT = 20;
// Engine FUN_7ff72bb6cbe0 applies DAT_7ff72c61f5e0 (1.0 m/s) as horizontal body velocity.
export const STEP_ENEMY_PATROL_SPEED = 100;

export class StepEnemy {
  readonly view = new Container();
  readonly params?: StepEnemyParams;
  readonly rect: Rect;

  constructor(readonly spawn: ActorSpawnDef) {
    this.params = parseStepEnemyParamsFromSpawn(spawn);
    this.rect = getStepEnemyRect(spawn);
    this.view.x = spawn.x;
    this.view.y = spawn.y;

    const direction = this.params?.direction ?? 0;
    const g = new Graphics();
    g.beginFill(0xff6b6b, 0.72);
    g.lineStyle(2, this.params ? 0xffd166 : 0x7a3030, 0.95);
    g.drawRoundedRect(-10, -10, 20, 20, 4);
    g.endFill();
    g.beginFill(0x2b1d1d, 0.65);
    const eyeOffset = direction < 0 ? -3 : direction > 0 ? 3 : 0;
    g.drawRect(-5 + eyeOffset, -4, 3, 3);
    g.drawRect(2 + eyeOffset, -4, 3, 3);
    g.endFill();
    this.view.addChild(g);
  }

  update(dt: number, tileMap?: TileMap): void {
    const direction = this.params?.direction;
    if (!direction) return;

    const sign = Math.sign(direction);
    const deltaX = sign * STEP_ENEMY_PATROL_SPEED * dt;
    const previousRect = { ...this.rect };
    const nextRect = { ...this.rect, x: this.rect.x + deltaX };
    if (tileMap?.rectHitsSolid(nextRect, { axis: 'x', sign, previousRect })) {
      this.params.direction = -direction;
      return;
    }

    this.rect.x += deltaX;
    this.view.x += deltaX;
  }
}

export function getStepEnemyRect(spawn: ActorSpawnDef): Rect {
  return {
    x: spawn.x - STEP_ENEMY_WIDTH / 2,
    y: spawn.y - STEP_ENEMY_HEIGHT / 2,
    width: STEP_ENEMY_WIDTH,
    height: STEP_ENEMY_HEIGHT,
  };
}

export function shouldRespawnPlayerForStepEnemy(playerRect: Rect, enemyRect: Rect, previousPlayerRect?: Rect): boolean {
  if (!(
    playerRect.x < enemyRect.x + enemyRect.width &&
    playerRect.x + playerRect.width > enemyRect.x &&
    playerRect.y < enemyRect.y + enemyRect.height &&
    playerRect.y + playerRect.height > enemyRect.y
  )) {
    return false;
  }

  return !isTopContact(playerRect, enemyRect, previousPlayerRect);
}

function isTopContact(playerRect: Rect, enemyRect: Rect, previousPlayerRect?: Rect): boolean {
  const enemyTop = enemyRect.y;
  const playerBottom = playerRect.y + playerRect.height;

  if (previousPlayerRect) {
    const previousBottom = previousPlayerRect.y + previousPlayerRect.height;
    return previousBottom <= enemyTop + 0.001 && playerBottom >= enemyTop;
  }

  const topOverlap = playerBottom - enemyTop;
  return playerRect.y < enemyTop && topOverlap >= 0 && topOverlap <= Math.min(6, enemyRect.height / 2);
}

export function parseStepEnemyParamsFromSpawn(spawn: ActorSpawnDef): StepEnemyParams | undefined {
  return parseStepEnemyParamsAfterCoordinatePair(spawn.raw, spawn.x, spawn.y);
}

export function parseStepEnemyParamsAfterCoordinatePair(
  raw: readonly ValueAtom[],
  x: number,
  y: number,
): StepEnemyParams | undefined {
  for (let index = 0; index <= raw.length - 2; index++) {
    if (raw[index] !== x || raw[index + 1] !== y) continue;

    const direction = raw[index + 2];
    if (direction === undefined) return { direction: undefined };
    if (!isFiniteNumber(direction)) continue;
    return { direction };
  }

  return undefined;
}

function isFiniteNumber(value: ValueAtom | undefined): value is number {
  return typeof value === 'number' && Number.isFinite(value);
}
