import type { Rect } from '../types';

export const PLAYER_RECT_WIDTH = 32;
export const PLAYER_RECT_HEIGHT = 46;
export const PLAYER_RECT_CENTER_OFFSET_X = 16;
export const PLAYER_RECT_CENTER_OFFSET_Y = 47;

/**
 * Convert the recovered Player actor coordinate into the same top-left rect
 * placement used by Player construction/reset. The source data treats x/y as
 * an anchor point near the player's feet, not as the rect's geometric center.
 */
export function getPlayerRectFromActorCoordinate(x: number, y: number): Rect {
  return {
    x: x - PLAYER_RECT_CENTER_OFFSET_X,
    y: y - PLAYER_RECT_CENTER_OFFSET_Y,
    width: PLAYER_RECT_WIDTH,
    height: PLAYER_RECT_HEIGHT,
  };
}
