import { Container, Graphics, Text, TextStyle } from 'pixi.js';
import type { ActorSpawnDef } from '../types';

// Recovered-data: StopWatchJudge ctor FUN_7ff72bb45b70 seeds actor+0x5d18 with
// 0.01f, draw helper FUN_7ff72bb463d0 formats TARGET TIME %02d:%02d, and
// update helper FUN_7ff72bb462d0 formats WINNER %02d:%02d from centiseconds.
const STOP_WATCH_JUDGE_DEFAULT_TARGET_SECONDS = 0.01;
const STOP_WATCH_JUDGE_EVENT_EPSILON_SECONDS = 1.19e-7;
const STOP_WATCH_JUDGE_RESULT_SLOT_LIMIT = 10;
const STOP_WATCH_JUDGE_EMPTY_RESULT_WORD = 0xffffffff;
// Recovered-data: base Judge update FUN_7ff72bb43480 advances state 10 by
// actor+0x51c += dt * 426.6666565f and enters state 0x14 only once the value
// is strictly greater than 1920.0f.
const STOP_WATCH_JUDGE_RESULT_CHARGE_RATE = Math.fround(426.6666565);
const STOP_WATCH_JUDGE_RESULT_CHARGE_LIMIT = Math.fround(1920);
const STOP_WATCH_JUDGE_RESULT_COHORT_BASE_SECONDS = Math.fround(1.5);
const STOP_WATCH_JUDGE_RESULT_COHORT_PLAYER_STEP_SECONDS = Math.fround(0.1);
const STOP_WATCH_JUDGE_STATE_IDLE = 0;
const STOP_WATCH_JUDGE_STATE_CHARGE = 10;
const STOP_WATCH_JUDGE_STATE_SYNC_WAIT = 0x14;
const STOP_WATCH_JUDGE_STATE_RESULT = 0x1e;
const STOP_WATCH_JUDGE_STATE_RESULT_WAIT = 0x1f;
// Recovered-data: base Judge FUN_7ff72bb43480 starts the result view with a
// 5.0f lifetime. UI manager FUN_7ff72bbe7c80 advances it with the fixed
// DAT_7ff72bcc6758 = 1/30 float32 step, independently of the Stage dt.
const STOP_WATCH_JUDGE_RESULT_VIEW_LIFETIME_SECONDS = Math.fround(5);
const STOP_WATCH_JUDGE_RESULT_VIEW_FIXED_SECONDS = Math.fround(1 / 30);
// Recovered-data: hidden vtable slot +0xc8 at 0x7ff72bb45de0 closes the
// working result snapshot after DAT_7ff72bc7d464 seconds without event 0x12.
export const STOP_WATCH_JUDGE_QUIET_WINDOW_SECONDS = Math.fround(0.1);

export interface StopWatchJudgeResultSlot {
  eventValue: number;
  centiseconds: number;
  cohortPresentationSeconds: number;
}

function makeEmptyResultSlot(): StopWatchJudgeResultSlot {
  return {
    eventValue: -1,
    centiseconds: STOP_WATCH_JUDGE_EMPTY_RESULT_WORD,
    cohortPresentationSeconds: 0,
  };
}

export class StopWatchJudgeActor {
  readonly view = new Container();
  readonly targetTimeText: Text;
  quietSeconds = 0;
  resultSnapshotClosed = false;
  baseJudgeState = STOP_WATCH_JUDGE_STATE_IDLE;
  resultCharge = 0;
  baseJudgeStateSeconds = 0;
  winnerEventValue: number | null = null;
  resultIsDraw = false;
  resultViewActive = false;
  resultViewLifetimeSeconds = Math.fround(-1);
  // Recovered-data: receiver FUN_7ff72bb46180 appends event-0xf payloads into
  // the first 10 result slots at actor+0x5d2c.
  readonly resultSlots: StopWatchJudgeResultSlot[] = [];
  readonly pendingLoserPresentationEventValues: number[] = [];
  // Recovered-data: ctor FUN_7ff72bb45b70 writes qword 0xffffffffffffffff at
  // each native slot start, spanning eventValue(+0) and centiseconds(+4), then
  // writes dword 0 at +8; receiver FUN_7ff72bb46180 fills slots by count.
  readonly resultSlotBuffer: StopWatchJudgeResultSlot[] = Array.from(
    { length: STOP_WATCH_JUDGE_RESULT_SLOT_LIMIT },
    makeEmptyResultSlot,
  );

  constructor(readonly spawn: ActorSpawnDef) {
    this.view.x = spawn.x;
    this.view.y = spawn.y;

    const plate = new Graphics();
    plate.beginFill(0x263442, 0.94);
    plate.lineStyle(2, 0xffffff, 0.9);
    plate.drawRoundedRect(-74, -14, 148, 28, 4);
    plate.endFill();
    this.view.addChild(plate);

    this.targetTimeText = new Text(
      formatStopWatchJudgeTargetTime(STOP_WATCH_JUDGE_DEFAULT_TARGET_SECONDS),
      new TextStyle({
        fill: 0xffffff,
        fontSize: 10,
        fontFamily: 'monospace',
        fontWeight: '700',
        align: 'center',
        stroke: 0x101820,
        strokeThickness: 2,
      }),
    );
    this.targetTimeText.anchor.set(0.5);
    this.view.addChild(this.targetTimeText);
  }

  showWinnerTime(remainingSeconds: number): void {
    this.targetTimeText.text = formatStopWatchJudgeWinnerTime(remainingSeconds);
  }

  beginResultFrame(dt: number, activePlayerCount: number): boolean {
    if (this.resultSnapshotClosed) return false;

    // Native fields and incoming timestep are float32. Preserve that rounding
    // so six 1/60 updates cross the dumped 0.1f boundary like retail.
    this.quietSeconds = Math.fround(this.quietSeconds + Math.fround(Math.max(0, dt)));
    if (this.quietSeconds >= STOP_WATCH_JUDGE_QUIET_WINDOW_SECONDS) {
      this.closeResultSnapshot(activePlayerCount);
      return true;
    }

    // Recovered-data: the state-0 tail of raw 0x7ff72bb45de0 resets the
    // logical count every Judge update. The backing native slot bytes remain
    // stale until the next event-0xf payload overwrites them, so keep the
    // browser buffer intact and reset only its logical view.
    this.resultSlots.length = 0;
    return false;
  }

  receiveRunningTimerHeartbeat(): void {
    if (!this.resultSnapshotClosed) this.quietSeconds = 0;
  }

  get resultChargeComplete(): boolean {
    return this.baseJudgeState === STOP_WATCH_JUDGE_STATE_SYNC_WAIT;
  }

  get resultDecisionComplete(): boolean {
    return this.baseJudgeState === STOP_WATCH_JUDGE_STATE_RESULT;
  }

  get resultPresentationComplete(): boolean {
    return this.baseJudgeState === STOP_WATCH_JUDGE_STATE_RESULT_WAIT
      && !this.resultViewActive;
  }

  advanceResultDecisionFrame(dt: number, activePlayerCount: number): boolean {
    this.pendingLoserPresentationEventValues.length = 0;
    if (this.baseJudgeState !== STOP_WATCH_JUDGE_STATE_SYNC_WAIT) return false;

    this.stableSortResultSlots();
    const bestCentiseconds = this.resultSlots[0]?.centiseconds;
    const cohortWindowSeconds = stopWatchJudgeCohortWindowSeconds(activePlayerCount);
    const frameSeconds = Math.fround(dt);

    // Recovered-data: raw StopWatchJudge slot +0xc8 scans from the worst
    // result toward the runner-up. The old timer must already be at/above the
    // window to skip it, so a frame that crosses the window still belongs to
    // that cohort and completion is observed on the next update.
    for (let slotIndex = this.resultSlots.length - 1; slotIndex >= 1; slotIndex -= 1) {
      const slot = this.resultSlots[slotIndex];
      if (slot.cohortPresentationSeconds >= cohortWindowSeconds) continue;
      if (unsignedResultWord(slot.centiseconds) === unsignedResultWord(bestCentiseconds)) continue;

      const cohortCentiseconds = unsignedResultWord(slot.centiseconds);
      for (
        let cohortIndex = slotIndex;
        cohortIndex >= 1
          && unsignedResultWord(this.resultSlots[cohortIndex].centiseconds) === cohortCentiseconds;
        cohortIndex -= 1
      ) {
        const cohortSlot = this.resultSlots[cohortIndex];
        this.pendingLoserPresentationEventValues.push(cohortSlot.eventValue);
        if (cohortSlot.cohortPresentationSeconds < cohortWindowSeconds) {
          cohortSlot.cohortPresentationSeconds = Math.fround(
            cohortSlot.cohortPresentationSeconds + frameSeconds,
          );
        }
      }
      return false;
    }

    this.commitResultDecision();
    return true;
  }

  advanceBaseJudgeFrame(dt: number): boolean {
    const frameSeconds = Math.fround(dt);
    let enteredSyncWait = false;

    if (this.baseJudgeState === STOP_WATCH_JUDGE_STATE_CHARGE) {
      const chargeStep = Math.fround(frameSeconds * STOP_WATCH_JUDGE_RESULT_CHARGE_RATE);
      this.resultCharge = Math.fround(this.resultCharge + chargeStep);
      if (STOP_WATCH_JUDGE_RESULT_CHARGE_LIMIT < this.resultCharge) {
        // FUN_7ff72bb43480 writes the state/state-seconds pair as one qword.
        this.baseJudgeState = STOP_WATCH_JUDGE_STATE_SYNC_WAIT;
        this.baseJudgeStateSeconds = 0;
        enteredSyncWait = true;
      }
    } else if (this.baseJudgeState === STOP_WATCH_JUDGE_STATE_RESULT) {
      // Recovered-data: FUN_7ff72bb43480 activates the common WINNER/DRAW
      // result view, advances 0x1e -> 0x1f, writes lifetime 5.0f, then the
      // common tail adds this frame's Stage dt to stateSeconds.
      this.resultViewActive = true;
      this.resultViewLifetimeSeconds = STOP_WATCH_JUDGE_RESULT_VIEW_LIFETIME_SECONDS;
      this.baseJudgeState = STOP_WATCH_JUDGE_STATE_RESULT_WAIT;
      this.baseJudgeStateSeconds = 0;
    }

    if (this.baseJudgeState !== STOP_WATCH_JUDGE_STATE_IDLE) {
      this.baseJudgeStateSeconds = Math.fround(this.baseJudgeStateSeconds + frameSeconds);
    }
    return enteredSyncWait;
  }

  advanceResultViewFrame(): boolean {
    if (
      this.baseJudgeState !== STOP_WATCH_JUDGE_STATE_RESULT_WAIT
      || !this.resultViewActive
    ) {
      return this.resultPresentationComplete;
    }

    this.resultViewLifetimeSeconds = Math.fround(
      this.resultViewLifetimeSeconds - STOP_WATCH_JUDGE_RESULT_VIEW_FIXED_SECONDS,
    );
    // FUN_7ff72bbeabd0 leaves the view active at exactly zero and dismisses it
    // only after the newly stored float32 lifetime becomes strictly negative.
    if (this.resultViewLifetimeSeconds < 0) this.resultViewActive = false;
    return this.resultPresentationComplete;
  }

  recordResultSlot(eventValue: number, remainingSeconds: number): void {
    if (this.resultSnapshotClosed) return;
    const slotIndex = this.resultSlots.length;
    if (slotIndex >= STOP_WATCH_JUDGE_RESULT_SLOT_LIMIT) return;

    const centiseconds = stopWatchJudgeResultCentiseconds(remainingSeconds);
    if (centiseconds === undefined) return;

    const resultSlot = { eventValue, centiseconds, cohortPresentationSeconds: 0 };
    this.resultSlots.push(resultSlot);
    this.resultSlotBuffer[slotIndex] = resultSlot;
  }

  private closeResultSnapshot(activePlayerCount: number): void {
    const representedPlayerIds = new Set(this.resultSlots.map((slot) => slot.eventValue));
    const participantLimit = Math.max(0, Math.trunc(activePlayerCount));
    for (let playerId = 0; playerId < participantLimit; playerId += 1) {
      if (representedPlayerIds.has(playerId)) continue;
      const slotIndex = this.resultSlots.length;
      if (slotIndex >= STOP_WATCH_JUDGE_RESULT_SLOT_LIMIT) break;
      const missingResult = {
        eventValue: playerId,
        centiseconds: STOP_WATCH_JUDGE_EMPTY_RESULT_WORD,
        cohortPresentationSeconds: 0,
      };
      this.resultSlots.push(missingResult);
      this.resultSlotBuffer[slotIndex] = missingResult;
    }

    // Recovered-data: the quiet-window self-command 9 reaches base handler
    // FUN_7ff72bb43670, whose offline path qword-writes state 10 and zero
    // state-seconds before the separate base update performs the charge.
    this.baseJudgeState = STOP_WATCH_JUDGE_STATE_CHARGE;
    this.baseJudgeStateSeconds = 0;
    this.resultSnapshotClosed = true;
  }

  private stableSortResultSlots(): void {
    for (let slotIndex = 1; slotIndex < this.resultSlots.length; slotIndex += 1) {
      const currentSlot = this.resultSlots[slotIndex];
      let insertIndex = slotIndex;
      while (
        insertIndex > 0
        && unsignedResultWord(currentSlot.centiseconds)
          < unsignedResultWord(this.resultSlots[insertIndex - 1].centiseconds)
      ) {
        this.resultSlots[insertIndex] = this.resultSlots[insertIndex - 1];
        insertIndex -= 1;
      }
      this.resultSlots[insertIndex] = currentSlot;
    }

    for (let slotIndex = 0; slotIndex < this.resultSlots.length; slotIndex += 1) {
      this.resultSlotBuffer[slotIndex] = this.resultSlots[slotIndex];
    }
  }

  private commitResultDecision(): void {
    const bestSlot = this.resultSlots[0];
    const bestCentiseconds = unsignedResultWord(bestSlot?.centiseconds);
    const hasFiniteBest = bestSlot !== undefined
      && bestCentiseconds !== STOP_WATCH_JUDGE_EMPTY_RESULT_WORD;
    const bestIsTied = hasFiniteBest && this.resultSlots
      .slice(1)
      .some((slot) => unsignedResultWord(slot.centiseconds) === bestCentiseconds);

    if (hasFiniteBest && !bestIsTied) {
      this.winnerEventValue = bestSlot.eventValue;
      this.resultIsDraw = false;
      this.targetTimeText.text = formatStopWatchJudgeWinnerCentiseconds(bestCentiseconds);
    } else {
      this.winnerEventValue = null;
      this.resultIsDraw = true;
      this.targetTimeText.text = 'DRAW';
    }

    // Raw 0x7ff72bb4606e..0x7ff72bb4609d writes state and seconds as one qword.
    this.baseJudgeState = STOP_WATCH_JUDGE_STATE_RESULT;
    this.baseJudgeStateSeconds = 0;
  }
}

export function formatStopWatchJudgeTargetTime(targetSeconds: number): string {
  const safeSeconds = Number.isFinite(targetSeconds) ? targetSeconds : 0;
  const seconds = clampInt(Math.trunc(safeSeconds), 0, 99);
  const centiseconds = clampInt(Math.trunc(Math.max(0, safeSeconds) * 100) % 100, 0, 99);
  return `TARGET TIME ${pad2(seconds)}:${pad2(centiseconds)}`;
}

export function formatStopWatchJudgeWinnerTime(remainingSeconds: number): string {
  const safeSeconds = Number.isFinite(remainingSeconds) ? Math.max(0, remainingSeconds) : 0;
  return formatStopWatchJudgeWinnerCentiseconds(Math.trunc(safeSeconds * 100));
}

function formatStopWatchJudgeWinnerCentiseconds(totalCentiseconds: number): string {
  const safeCentiseconds = Number.isFinite(totalCentiseconds)
    ? Math.max(0, Math.trunc(totalCentiseconds))
    : 0;
  const seconds = clampInt(Math.trunc(safeCentiseconds / 100), 0, 99);
  const centiseconds = clampInt(safeCentiseconds % 100, 0, 99);
  return `WINNER ${pad2(seconds)}:${pad2(centiseconds)}`;
}

export function stopWatchJudgeResultCentiseconds(remainingSeconds: number): number | undefined {
  const floatSeconds = Math.fround(remainingSeconds);
  if (!Number.isFinite(floatSeconds) || Math.abs(floatSeconds) <= STOP_WATCH_JUDGE_EVENT_EPSILON_SECONDS) {
    return undefined;
  }
  // FUN_7ff72bb46180 multiplies two float32 operands before truncating.
  return Math.trunc(Math.fround(floatSeconds * 100)) >>> 0;
}

function stopWatchJudgeCohortWindowSeconds(activePlayerCount: number): number {
  const playerCountDelta = Math.fround(Math.trunc(activePlayerCount) - 2);
  const playerCountAdjustment = Math.fround(
    playerCountDelta * STOP_WATCH_JUDGE_RESULT_COHORT_PLAYER_STEP_SECONDS,
  );
  return Math.fround(STOP_WATCH_JUDGE_RESULT_COHORT_BASE_SECONDS - playerCountAdjustment);
}

function unsignedResultWord(value: number | undefined): number {
  return (value ?? STOP_WATCH_JUDGE_EMPTY_RESULT_WORD) >>> 0;
}

function clampInt(value: number, min: number, max: number): number {
  return Math.min(max, Math.max(min, value));
}

function pad2(value: number): string {
  return String(value).padStart(2, '0');
}
