import { picoRandom } from 'campaign-random';
import { Container, Graphics } from 'pixi.js';
import type { ActorSpawnDef, Rect, ValueAtom } from '../types';

export const ROULETTE_LIFT_NATIVE_TICK_SECONDS = 1 / 60;
export const ROULETTE_LIFT_PLATFORM_WIDTH = 118;
export const ROULETTE_LIFT_PLATFORM_HEIGHT = 18;
export const ROULETTE_LIFT_TRIGGER_WIDTH = 58;
export const ROULETTE_LIFT_TRIGGER_HEIGHT = 58;

const ROULETTE_LIFT_PLATFORM_OFFSET_X = -59;
const ROULETTE_LIFT_PLATFORM_OFFSET_Y = -9;
const ROULETTE_LIFT_TRIGGER_OFFSET_X = -29;
const ROULETTE_LIFT_TRIGGER_OFFSET_Y = -139;
const ROULETTE_LIFT_DEFAULT_TRAVEL = -40;
const ROULETTE_LIFT_DEFAULT_INTERVAL_SECONDS = 0.5;
const ROULETTE_LIFT_ADVANCE_STEP = 1;
const ROULETTE_LIFT_RETURN_STEP = 1;
const ROULETTE_LIFT_INITIAL_MODULUS = 2;
const ROULETTE_LIFT_SETTLED_EPSILON = Math.fround(0.001);
const ROULETTE_LIFT_NO_RIDER_RESET_SECONDS = Math.fround(2);

export interface RouletteLiftParams {
  travelPerRound: number;
  stateIntervalSeconds: number;
  partnerName: string;
}

export type RouletteLiftContactResult = 'ignored' | 'busy' | 'win' | 'reset';
export type RouletteLiftRandomIndex = (maxInclusive: number) => number;

export class RouletteLift {
  readonly view = new Container();
  readonly params: RouletteLiftParams;
  readonly platformRect: Rect;
  readonly triggerRect: Rect;
  readonly nativeName: string;
  partner?: RouletteLift;
  ownsStateClock = false;
  offset = 0;
  round = 0;
  stateClockSeconds = 0;
  rouletteState = 0;
  stateModulus = ROULETTE_LIFT_INITIAL_MODULUS;
  noUpNeighborSeconds = 0;

  private readonly randomIndex: RouletteLiftRandomIndex;

  constructor(readonly spawn: ActorSpawnDef, randomIndex: RouletteLiftRandomIndex = defaultRandomIndex) {
    this.params = parseRouletteLiftParamsFromSpawn(spawn);
    this.randomIndex = randomIndex;
    this.nativeName = `${spawn.actorName}${spawn.label}`;
    this.view.x = spawn.x;
    this.view.y = spawn.y;
    this.platformRect = {
      x: spawn.x + ROULETTE_LIFT_PLATFORM_OFFSET_X,
      y: spawn.y + ROULETTE_LIFT_PLATFORM_OFFSET_Y,
      width: ROULETTE_LIFT_PLATFORM_WIDTH,
      height: ROULETTE_LIFT_PLATFORM_HEIGHT,
    };
    this.triggerRect = {
      x: spawn.x + ROULETTE_LIFT_TRIGGER_OFFSET_X,
      y: spawn.y + ROULETTE_LIFT_TRIGGER_OFFSET_Y,
      width: ROULETTE_LIFT_TRIGGER_WIDTH,
      height: ROULETTE_LIFT_TRIGGER_HEIGHT,
    };

    // The exact native glyph/font and strike-bump presentation remain separate.
    // These two fallback shapes expose the recovered solid body geometry now.
    const platform = new Graphics();
    platform.beginFill(0x8bd3ff, 0.72);
    platform.lineStyle(2, 0xffffff, 0.9);
    platform.drawRoundedRect(
      ROULETTE_LIFT_PLATFORM_OFFSET_X,
      ROULETTE_LIFT_PLATFORM_OFFSET_Y,
      ROULETTE_LIFT_PLATFORM_WIDTH,
      ROULETTE_LIFT_PLATFORM_HEIGHT,
      4,
    );
    platform.endFill();
    const trigger = new Graphics();
    trigger.beginFill(0xf4d35e, 0.78);
    trigger.lineStyle(2, 0xffffff, 0.9);
    trigger.drawRect(
      ROULETTE_LIFT_TRIGGER_OFFSET_X,
      ROULETTE_LIFT_TRIGGER_OFFSET_Y,
      ROULETTE_LIFT_TRIGGER_WIDTH,
      ROULETTE_LIFT_TRIGGER_HEIGHT,
    );
    trigger.endFill();
    this.view.addChild(platform, trigger);
  }

  get bodyRects(): readonly Rect[] {
    return [this.platformRect, this.triggerRect];
  }

  get busy(): boolean {
    if (
      this.partner
      && (this.partner.round >>> 0) < (this.round >>> 0)
    ) return true;
    const targetOffset = Math.fround(
      Math.fround(this.round >>> 0) * this.params.travelPerRound,
    );
    return ROULETTE_LIFT_SETTLED_EPSILON < Math.abs(Math.fround(this.offset - targetOffset));
  }

  bindPartner(candidates: readonly RouletteLift[]): void {
    if (this.partner || this.params.partnerName === '') return;
    const partner = candidates.find((candidate) => (
      candidate !== this && candidate.nativeName === this.params.partnerName
    ));
    if (!partner) return;

    this.partner = partner;
    // Native lazy resolution makes the first resolver whose target is still
    // unbound the clock owner. Browser createTable visitation is deterministic.
    if (!partner.partner) this.ownsStateClock = true;
  }

  handleUpperBodyContact(contactVectorY: number): RouletteLiftContactResult {
    if (!(contactVectorY > 0)) return 'ignored';
    if (this.busy) return 'busy';

    if (this.rouletteState === 0) {
      this.round = (this.round + 1) >>> 0;
      this.rouletteState = 1;
      this.stateClockSeconds = 0;
      this.stateModulus = boundedRandomIndex(this.randomIndex(2), 2) + 2;
      return 'win';
    }

    this.round = 0;
    if (this.partner) this.partner.round = 0;
    return 'reset';
  }

  advanceNativeTick(
    dtSeconds: number,
    hasDirectUpNeighbor: boolean,
    canCommitMovement: (deltaY: number) => boolean,
  ): number {
    const frameSeconds = Number.isFinite(dtSeconds) ? Math.fround(Math.max(0, dtSeconds)) : 0;

    if (!this.busy) {
      if (
        this.partner?.ownsStateClock
        && !this.partner.busy
      ) {
        this.stateClockSeconds = this.partner.stateClockSeconds;
      }
      this.stateClockSeconds = Math.fround(this.stateClockSeconds + frameSeconds);
      if (this.params.stateIntervalSeconds <= this.stateClockSeconds) {
        this.rouletteState = (this.rouletteState + 1) % this.stateModulus;
        this.stateClockSeconds = 0;
      }
    }

    if (this.round !== 0) {
      if (hasDirectUpNeighbor) {
        this.noUpNeighborSeconds = 0;
      } else {
        this.noUpNeighborSeconds = Math.fround(this.noUpNeighborSeconds + frameSeconds);
        if (this.noUpNeighborSeconds >= ROULETTE_LIFT_NO_RIDER_RESET_SECONDS) {
          this.round = 0;
          if (this.partner) this.partner.round = 0;
          // Native clears only the expiring member's timer. Paired/contact
          // resets intentionally retain any partial timer on either member.
          this.noUpNeighborSeconds = 0;
        }
      }
    }

    const targetMagnitude = Math.abs(Math.fround(
      Math.fround(this.round >>> 0) * this.params.travelPerRound,
    ));
    const currentMagnitude = Math.abs(this.offset);
    const nextMagnitude = this.round !== 0
      ? Math.min(currentMagnitude + ROULETTE_LIFT_ADVANCE_STEP, targetMagnitude)
      : Math.max(currentMagnitude - ROULETTE_LIFT_RETURN_STEP, 0);
    const directionSign = this.params.travelPerRound < 0 ? -1 : 1;
    const nextOffset = Math.fround(directionSign * nextMagnitude);
    const deltaY = Math.fround(nextOffset - this.offset);
    if (deltaY === 0 || !canCommitMovement(deltaY)) return 0;

    this.offset = nextOffset;
    this.view.y = Math.fround(this.spawn.y + this.offset);
    this.platformRect.y = Math.fround(
      this.spawn.y + ROULETTE_LIFT_PLATFORM_OFFSET_Y + this.offset,
    );
    this.triggerRect.y = Math.fround(
      this.spawn.y + ROULETTE_LIFT_TRIGGER_OFFSET_Y + this.offset,
    );
    return deltaY;
  }
}

export function parseRouletteLiftParamsFromSpawn(spawn: ActorSpawnDef): RouletteLiftParams {
  const defaults: RouletteLiftParams = {
    travelPerRound: ROULETTE_LIFT_DEFAULT_TRAVEL,
    stateIntervalSeconds: Math.fround(ROULETTE_LIFT_DEFAULT_INTERVAL_SECONDS),
    partnerName: '',
  };
  const { raw, x, y } = spawn;
  for (let index = 0; index <= raw.length - 2; index += 1) {
    if (raw[index] !== x || raw[index + 1] !== y) continue;
    const travel = raw[index + 2];
    const interval = raw[index + 3];
    const partnerName = raw[index + 4];
    return {
      travelPerRound: isFiniteNumber(travel) ? Math.fround(travel) : defaults.travelPerRound,
      stateIntervalSeconds: isFiniteNumber(interval)
        ? Math.fround(interval)
        : defaults.stateIntervalSeconds,
      partnerName: typeof partnerName === 'string' ? partnerName : defaults.partnerName,
    };
  }
  return defaults;
}

function defaultRandomIndex(maxInclusive: number): number {
  return Math.floor(picoRandom() * (Math.max(0, Math.trunc(maxInclusive)) + 1));
}

function boundedRandomIndex(value: number, maxInclusive: number): number {
  if (!Number.isFinite(value)) return 0;
  return Math.max(0, Math.min(maxInclusive, Math.trunc(value)));
}

function isFiniteNumber(value: ValueAtom | undefined): value is number {
  return typeof value === 'number' && Number.isFinite(value);
}
