import { Container, Graphics } from 'pixi.js';
import type { ActorSpawnDef, ValueAtom } from '../types';

export interface JumpSwitchParams {
  state: number;
  impulse: number;
  targetLabel: string;
}

const DEFAULT_STATE = 0;
const DEFAULT_IMPULSE = 0;

export class JumpSwitch {
  readonly view = new Container();
  readonly params: JumpSwitchParams;

  constructor(readonly spawn: ActorSpawnDef) {
    this.params = parseJumpSwitchParamsFromSpawn(spawn);
    this.view.x = spawn.x;
    this.view.y = spawn.y;

    const g = new Graphics();
    g.beginFill(0x22c55e, 0.28);
    g.lineStyle(2, 0x86efac, 0.9);
    g.drawRoundedRect(-18, -7, 36, 14, 4);
    g.endFill();
    g.beginFill(0xffffff, 0.55);
    g.drawPolygon([-8, 2, 0, -6, 8, 2]);
    g.endFill();
    this.view.addChild(g);
  }
}

export function parseJumpSwitchParamsFromSpawn(spawn: ActorSpawnDef): JumpSwitchParams {
  const params = parseJumpSwitchAfterCoordinatePair(spawn.raw, spawn.x, spawn.y);

  return {
    state: params?.state ?? DEFAULT_STATE,
    impulse: params?.impulse ?? DEFAULT_IMPULSE,
    targetLabel: spawn.label,
  };
}

export function parseJumpSwitchAfterCoordinatePair(
  raw: readonly ValueAtom[],
  x: number,
  y: number,
): { state: number; impulse: number } | undefined {
  for (let index = 0; index <= raw.length - 4; index += 1) {
    if (raw[index] !== x || raw[index + 1] !== y) continue;

    const state = raw[index + 2];
    const impulse = raw[index + 3];
    if (
      typeof state === 'number'
      && Number.isFinite(state)
      && typeof impulse === 'number'
      && Number.isFinite(impulse)
    ) {
      return { state, impulse };
    }
  }

  return undefined;
}
