import { Container, Graphics } from 'pixi.js';
import type { ActorSpawnDef, Rect, ValueAtom } from '../types';

export interface SwitchRectParams {
  width: number;
  height: number;
}

export class SwitchRect {
  readonly view = new Container();
  readonly rect: Rect;
  readonly params?: SwitchRectParams;
  // Legacy source-state compatibility. Native SwitchRect is a named command receiver, never a
  // Player/PushBox-overlap Switch source, so this flag intentionally stays false.
  pressed = false;
  activationCount = 0;
  activationRequested = false;
  collisionPublished = false;

  constructor(readonly spawn: ActorSpawnDef) {
    this.params = parseSwitchRectParamsFromSpawn(spawn);
    this.view.x = spawn.x;
    this.view.y = spawn.y;

    const width = this.params?.width ?? 48;
    const height = this.params?.height ?? 48;
    this.rect = { x: spawn.x - width / 2, y: spawn.y - height / 2, width, height };
    this.view.visible = false;
    const g = new Graphics();
    g.beginFill(0x5ec8ff, 0.2);
    g.lineStyle(2, this.params ? 0x5ec8ff : 0x607080, 0.9);
    g.drawRoundedRect(-width / 2, -height / 2, width, height, Math.max(3, Math.min(width, height) * 0.08));
    g.endFill();
    g.beginFill(0xffffff, 0.34);
    g.drawRect(-width / 2 + 4, -2, Math.max(0, width - 8), 4);
    g.drawRect(-2, -height / 2 + 4, 4, Math.max(0, height - 8));
    g.endFill();
    this.view.addChild(g);
  }

  // Recovered FUN_7ff72bb5bfd0: command 9 increments the producer hold count and only the
  // 0 -> 1 edge requests activation. Command 10 is zero-guarded and only 1 -> 0 deactivates.
  // Solid-body publication after activation is a separate collision-clear runtime slice.
  receiveCommand(command: 9 | 10): void {
    if (command === 9) {
      this.activationCount += 1;
      if (this.activationCount === 1) this.setActivationRequested(true);
      return;
    }

    if (this.activationCount === 0) return;
    this.activationCount -= 1;
    if (this.activationCount === 0) this.setActivationRequested(false);
  }

  // Recovered FUN_7ff72bb5bf60 publishes a pending slab only after its proposed body region is
  // clear. The final command-10 edge bypasses this deferred path and unpublishes immediately.
  updateCollisionPublication(regionClear: boolean): void {
    if (!this.activationRequested) {
      this.collisionPublished = false;
      return;
    }
    if (regionClear) this.collisionPublished = true;
  }

  private setActivationRequested(active: boolean): void {
    this.activationRequested = active;
    if (!active) this.collisionPublished = false;
    this.view.visible = active;
  }
}

export function parseSwitchRectParamsFromSpawn(spawn: ActorSpawnDef): SwitchRectParams | undefined {
  return parseSwitchRectParamsAfterCoordinatePair(spawn.raw, spawn.x, spawn.y);
}

export function parseSwitchRectParamsAfterCoordinatePair(
  raw: readonly ValueAtom[],
  x: number,
  y: number,
): SwitchRectParams | undefined {
  for (let index = 0; index <= raw.length - 4; index++) {
    if (raw[index] !== x || raw[index + 1] !== y) continue;

    const width = raw[index + 2];
    const height = raw[index + 3];
    if (isPositiveFiniteNumber(width) && isPositiveFiniteNumber(height)) {
      return { width, height };
    }
  }

  return undefined;
}

function isPositiveFiniteNumber(value: ValueAtom | undefined): value is number {
  return typeof value === 'number' && Number.isFinite(value) && value > 0;
}
