import { Container, Graphics } from 'pixi.js';
import type { ActorSpawnDef, Rect, ValueAtom } from '../types';

export interface BlinkBlockParams {
  phase: number;
}

const DEFAULT_PHASE = 0;
const SMALL_BLOCK_SIZE = 32;
const LARGE_BLOCK_SIZE = 48;
const BLINK_BLOCK_PHASE_SECONDS = 1;

export class BlinkBlock {
  readonly view = new Container();
  readonly rect: Rect;
  readonly params: BlinkBlockParams;
  solid: boolean;
  private elapsed = 0;
  private reactivationRejected = false;

  constructor(readonly spawn: ActorSpawnDef, stageScale = 1) {
    this.params = parseBlinkBlockParamsFromSpawn(spawn);
    this.solid = true;
    const blockSize = stageScale <= 1 ? SMALL_BLOCK_SIZE : LARGE_BLOCK_SIZE;
    this.rect = {
      x: spawn.x + 1,
      y: spawn.y + 1,
      width: blockSize - 2,
      height: blockSize - 2,
    };
    this.view.x = spawn.x;
    this.view.y = spawn.y;
    this.view.alpha = this.solid ? 1 : 0.32;

    const g = new Graphics();
    g.beginFill(0x4cc9f0, 0.62);
    g.lineStyle(2, 0xf8f9fa, 0.86);
    g.drawRect(0, 0, blockSize, blockSize);
    g.endFill();
    g.beginFill(0xffffff, 0.34);
    g.drawRect(5, 5, blockSize - 10, 5);
    g.endFill();
    this.view.addChild(g);
  }

  update(dt: number, canReactivate = true): void {
    this.elapsed += dt;
    if (this.reactivationRejected) {
      // Native FUN_7ff72bb35730 consumes the failed publication edge on the
      // following update, leaves the body inactive, and restarts the cadence.
      this.reactivationRejected = false;
      this.elapsed = 0;
    } else if (this.elapsed >= BLINK_BLOCK_PHASE_SECONDS) {
      if (this.solid) {
        this.solid = false;
        this.elapsed = 0;
      } else if (canReactivate) {
        this.solid = true;
        this.elapsed = 0;
      } else {
        this.reactivationRejected = true;
      }
    }
    this.view.alpha = this.solid ? 1 : 0.32;
  }
}

export function parseBlinkBlockParamsFromSpawn(spawn: ActorSpawnDef): BlinkBlockParams {
  void spawn;
  return {
    phase: DEFAULT_PHASE,
  };
}

export function parseBlinkBlockPhaseAfterCoordinatePair(
  raw: readonly ValueAtom[],
  x: number,
  y: number,
): number | undefined {
  for (let index = 0; index <= raw.length - 3; index += 1) {
    if (raw[index] !== x || raw[index + 1] !== y) continue;

    const phase = raw[index + 2];
    if (typeof phase === 'number' && Number.isFinite(phase)) {
      return phase;
    }
  }

  return undefined;
}

function parseBlinkBlockPhaseFromLabel(label: string): number | undefined {
  if (!/^-?\d+$/.test(label)) return undefined;
  const phase = Number(label);
  return Number.isFinite(phase) ? phase : undefined;
}
