import { Container, Graphics } from 'pixi.js';
import type { ActorSpawnDef, Rect, ValueAtom } from '../types';

export interface DelaySwitchParams {
  delay: number;
}

const DEFAULT_DELAY = 0;

export class DelaySwitch {
  readonly view = new Container();
  readonly rect: Rect;
  readonly params: DelaySwitchParams;
  pressed = false;

  constructor(readonly spawn: ActorSpawnDef) {
    this.params = parseDelaySwitchParamsFromSpawn(spawn);
    this.rect = { x: spawn.x - 18, y: spawn.y - 8, width: 36, height: 16 };
    this.view.x = spawn.x;
    this.view.y = spawn.y;

    const g = new Graphics();
    g.beginFill(0xf2c94c, 0.26);
    g.lineStyle(2, 0xd89b1d, 0.9);
    g.drawRoundedRect(-18, -8, 36, 16, 4);
    g.endFill();
    g.beginFill(0xffffff, 0.45);
    g.drawRect(-10, -2, 20, 4);
    g.endFill();
    this.view.addChild(g);
  }

  press(): void {
    this.pressed = true;
    this.view.alpha = 0.55;
    this.view.scale.y = 0.65;
  }
}

export function parseDelaySwitchParamsFromSpawn(spawn: ActorSpawnDef): DelaySwitchParams {
  return {
    delay: parseDelaySwitchDelayAfterCoordinatePair(spawn.raw, spawn.x, spawn.y) ?? DEFAULT_DELAY,
  };
}

export function parseDelaySwitchDelayAfterCoordinatePair(
  raw: readonly ValueAtom[],
  x: number,
  y: number,
): number | undefined {
  for (let index = 0; index <= raw.length - 3; index += 1) {
    if (raw[index] !== x || raw[index + 1] !== y) continue;

    const delay = raw[index + 2];
    if (typeof delay === 'number' && Number.isFinite(delay)) {
      return delay;
    }
  }

  return undefined;
}
