import { Container, Graphics } from 'pixi.js';
import type { ActorSpawnDef, Rect, ValueAtom } from '../types';

export interface BowwowEnemyParams {
  chaseStepPerFrame: number;
}

export interface BowwowEnemyTarget {
  x: number;
  y: number;
  movementX: number;
  movementY: number;
}

export class BowwowEnemy {
  readonly view = new Container();
  readonly params: BowwowEnemyParams;
  readonly rect: Rect;
  private state: BowwowEnemyState = 0;
  private sleepBobSeconds = 0;
  private lastChaseDelta = { x: 0, y: 0 };

  constructor(readonly spawn: ActorSpawnDef) {
    this.params = parseBowwowEnemyParamsFromSpawn(spawn);
    this.rect = getBowwowEnemyRect(spawn);
    this.view.x = spawn.x;
    this.view.y = spawn.y;

    const g = new Graphics();
    g.beginFill(0x2b2f77, 0.72);
    g.lineStyle(2, 0xf97316, 0.95);
    g.drawRoundedRect(-14, -11, 28, 22, 5);
    g.endFill();
    g.beginFill(0xffffff, 0.72);
    g.drawRect(-7, -4, 3, 3);
    g.drawRect(4, -4, 3, 3);
    g.endFill();
    g.lineStyle(2, 0xf97316, 0.7);
    g.moveTo(-10, 10);
    g.lineTo(-14, 15);
    g.moveTo(10, 10);
    g.lineTo(14, 15);
    this.view.addChild(g);
  }

  update(dt: number, targets: readonly BowwowEnemyTarget[] = []): void {
    const candidate = this.selectTarget(targets);

    if (this.state === 0) {
      this.applySleepBob(dt);
      if (candidate) this.state = 1;
      return;
    }

    if (this.state === 1) {
      this.applySleepBob(dt);
      if (candidate && candidate.movement > BOWWOW_WAKE_MOVEMENT_THRESHOLD) {
        this.state = 2;
      }
      return;
    }

    if (this.state === 2) {
      if (!candidate) {
        this.state = 0;
        return;
      }
      if (candidate.movement > BOWWOW_CHASE_MOVEMENT_THRESHOLD) {
        this.state = 3;
      }
      return;
    }

    if (this.state === 3) {
      if (candidate) {
        this.chase(candidate.target);
      }
      return;
    }

    this.translate(this.lastChaseDelta.x, this.lastChaseDelta.y);
  }

  private selectTarget(targets: readonly BowwowEnemyTarget[]): BowwowEnemyTargetCandidate | undefined {
    const rangeX = this.state === 0 ? BOWWOW_SLEEP_RANGE_X : BOWWOW_ACTIVE_RANGE_X;
    let selected: BowwowEnemyTargetCandidate | undefined;
    for (const target of targets) {
      if (Math.abs(target.x - this.view.x) >= rangeX) continue;
      const movement = Math.hypot(target.movementX, target.movementY);
      if (!selected || movement > selected.movement) {
        selected = { target, movement };
      }
    }
    return selected;
  }

  private applySleepBob(dt: number): void {
    const previousOffset = Math.sin(this.sleepBobSeconds * 2) * BOWWOW_SLEEP_BOB_AMPLITUDE;
    this.sleepBobSeconds += dt;
    const doubledPhase = this.sleepBobSeconds * 2;
    if (doubledPhase >= TAU) {
      this.sleepBobSeconds = (doubledPhase - TAU) * 0.5;
    }
    const nextOffset = Math.sin(this.sleepBobSeconds * 2) * BOWWOW_SLEEP_BOB_AMPLITUDE;
    this.translate(0, nextOffset - previousOffset);
  }

  private chase(target: BowwowEnemyTarget): void {
    const dx = target.x - this.view.x;
    const dy = target.y - (this.view.y + BOWWOW_CHASE_SOURCE_Y_OFFSET);
    const length = Math.hypot(dx, dy);
    if (length === 0) return;

    this.lastChaseDelta = {
      x: (dx / length) * this.params.chaseStepPerFrame,
      y: (dy / length) * this.params.chaseStepPerFrame,
    };
    this.translate(this.lastChaseDelta.x, this.lastChaseDelta.y);
  }

  private translate(dx: number, dy: number): void {
    this.rect.x += dx;
    this.rect.y += dy;
    this.view.x += dx;
    this.view.y += dy;
  }
}

type BowwowEnemyState = 0 | 1 | 2 | 3 | 4;
type BowwowEnemyTargetCandidate = { target: BowwowEnemyTarget; movement: number };

export const BOWWOW_ENEMY_WIDTH = 28;
export const BOWWOW_ENEMY_HEIGHT = 22;
// Recovered-data: BowwowEnemy ctor FUN_7ff72bb38ba0 defaults +0x40c to 1.0,
// applyParams FUN_7ff72bb39110 stores Lua param[0] there, and update
// FUN_7ff72bb39180 uses it as a normalized per-frame chase step after the
// sleep/wake movement gates below.
export const BOWWOW_ENEMY_DEFAULT_CHASE_STEP_PER_FRAME = 1;
export const BOWWOW_SLEEP_RANGE_X = 300;
export const BOWWOW_ACTIVE_RANGE_X = 400;
export const BOWWOW_WAKE_MOVEMENT_THRESHOLD = 1.5;
export const BOWWOW_CHASE_MOVEMENT_THRESHOLD = 2.5;
export const BOWWOW_CHASE_SOURCE_Y_OFFSET = 64;
export const BOWWOW_SLEEP_BOB_AMPLITUDE = 8;
const TAU = Math.PI * 2;

export function getBowwowEnemyRect(spawn: ActorSpawnDef): Rect {
  return {
    x: spawn.x - BOWWOW_ENEMY_WIDTH / 2,
    y: spawn.y - BOWWOW_ENEMY_HEIGHT / 2,
    width: BOWWOW_ENEMY_WIDTH,
    height: BOWWOW_ENEMY_HEIGHT,
  };
}

export function shouldRespawnPlayerForBowwowEnemy(playerRect: Rect, enemyRect: Rect): boolean {
  return (
    playerRect.x < enemyRect.x + enemyRect.width &&
    playerRect.x + playerRect.width > enemyRect.x &&
    playerRect.y < enemyRect.y + enemyRect.height &&
    playerRect.y + playerRect.height > enemyRect.y
  );
}

export function parseBowwowEnemyParamsFromSpawn(spawn: ActorSpawnDef): BowwowEnemyParams {
  return {
    chaseStepPerFrame: parseBowwowEnemyChaseStepAfterCoordinatePair(spawn.raw, spawn.x, spawn.y)
      ?? BOWWOW_ENEMY_DEFAULT_CHASE_STEP_PER_FRAME,
  };
}

export function parseBowwowEnemyChaseStepAfterCoordinatePair(
  raw: readonly ValueAtom[],
  x: number,
  y: number,
): number | undefined {
  for (let index = 0; index <= raw.length - 3; index += 1) {
    if (raw[index] !== x || raw[index + 1] !== y) continue;

    const chaseStep = raw[index + 2];
    if (typeof chaseStep === 'number' && Number.isFinite(chaseStep)) {
      return chaseStep;
    }
  }

  return undefined;
}
