import { Container, Graphics } from 'pixi.js';
import type { ActorSpawnDef, Rect, ValueAtom } from '../types';

export interface ScaleSwitchParams {
  scaleDelta: number;
}

const DEFAULT_SCALE_DELTA = 0;

export class ScaleSwitch {
  readonly view = new Container();
  readonly rect: Rect;
  readonly params: ScaleSwitchParams;
  pressed = false;

  constructor(readonly spawn: ActorSpawnDef) {
    this.params = parseScaleSwitchParamsFromSpawn(spawn);
    this.rect = { x: spawn.x - 18, y: spawn.y - 8, width: 36, height: 16 };
    this.view.x = spawn.x;
    this.view.y = spawn.y;

    const g = new Graphics();
    g.beginFill(this.params.scaleDelta < 0 ? 0x6ee7b7 : 0x93c5fd, 0.28);
    g.lineStyle(2, this.params.scaleDelta < 0 ? 0x10b981 : 0x3b82f6, 0.95);
    g.drawRoundedRect(-18, -8, 36, 16, 4);
    g.endFill();
    g.beginFill(0xffffff, 0.52);
    g.drawRect(-10, -2, 20, 4);
    g.endFill();
    this.view.addChild(g);
  }

  press(): void {
    this.pressed = true;
    this.view.alpha = 0.55;
    this.view.scale.y = 0.65;
  }
}

export function parseScaleSwitchParamsFromSpawn(spawn: ActorSpawnDef): ScaleSwitchParams {
  return {
    scaleDelta: parseScaleSwitchDeltaAfterCoordinatePair(spawn.raw, spawn.x, spawn.y) ?? DEFAULT_SCALE_DELTA,
  };
}

export function parseScaleSwitchDeltaAfterCoordinatePair(
  raw: readonly ValueAtom[],
  x: number,
  y: number,
): number | undefined {
  for (let index = 0; index <= raw.length - 3; index += 1) {
    if (raw[index] !== x || raw[index + 1] !== y) continue;

    const delta = raw[index + 2];
    if (typeof delta === 'number' && Number.isFinite(delta)) {
      return delta;
    }
  }

  return undefined;
}
