import { Container, Graphics } from 'pixi.js';
import type { ActorSpawnDef, Rect, Vector2 } from '../types';
import { resolveClosedGateCollision } from './KeyGate';

export const FALL_BOX_DEFAULT_SIZE = 32;
export const FALL_BOX_ARM_DELAY_SECONDS = 0.22;
export const FALL_BOX_SETTLE_STEP = 0.65;
export const FALL_BOX_NATIVE_SCREEN_WIDTH = 1280;
export const FALL_BOX_NATIVE_SCREEN_HEIGHT = 720;
export const FALL_BOX_OFFSCREEN_MARGIN = 1;

const TOP_CONTACT_DEPTH = 8;
const MIN_HORIZONTAL_OVERLAP = 6;

export interface FallBoxSize {
  width: number;
  height: number;
}

export interface FallingFallBoxVelocity {
  y: number;
  armedSeconds: number;
}

export interface FallBoxIntegrationResult {
  rect: Rect;
  velocity: FallingFallBoxVelocity;
}

export interface FallBoxCollisionResult {
  playerRect: Rect;
  playerVelocity: Vector2;
  grounded: boolean;
  blocked: boolean;
  triggeredBoxIndices: number[];
}

export class FallBox {
  readonly view = new Container();
  rect: Rect;
  velocity: FallingFallBoxVelocity = { y: 0, armedSeconds: 0 };
  falling = false;
  active = true;

  constructor(readonly spawn: ActorSpawnDef) {
    const size = getFallBoxSize(spawn);
    this.rect = {
      x: spawn.x - size.width / 2,
      y: spawn.y - size.height / 2,
      width: size.width,
      height: size.height,
    };

    const g = new Graphics();
    g.beginFill(0x7f8794, 1);
    g.lineStyle(3, 0x2f3540, 1);
    g.drawRoundedRect(0, 0, size.width, size.height, 3);
    g.endFill();
    g.lineStyle(2, 0xc7d0dc, 0.75);
    g.moveTo(5, 5);
    g.lineTo(size.width - 5, 5);
    g.moveTo(5, size.height - 5);
    g.lineTo(size.width - 5, size.height - 5);
    this.view.addChild(g);
    this.syncView();
  }

  trigger(): void {
    if (this.falling) return;
    this.falling = true;
    this.velocity = { y: 0, armedSeconds: 0 };
    this.view.alpha = 0.9;
  }

  updateFalling(dt: number, supported = false): void {
    if (!this.falling) return;
    const result = integrateFallingFallBox(this.rect, this.velocity, dt, supported);
    this.rect = result.rect;
    this.velocity = result.velocity;
    this.syncView();
  }

  setActive(active: boolean): void {
    this.active = active;
    this.view.visible = active;
  }

  private syncView(): void {
    this.view.x = this.rect.x;
    this.view.y = this.rect.y;
  }
}

export function getFallBoxSize(spawn: ActorSpawnDef): FallBoxSize {
  const width = spawn.raw[6];
  const height = spawn.raw[7];
  if (isPositiveFiniteNumber(width) && isPositiveFiniteNumber(height)) {
    return { width, height };
  }
  return { width: FALL_BOX_DEFAULT_SIZE, height: FALL_BOX_DEFAULT_SIZE };
}

export function integrateFallingFallBox(
  rect: Rect,
  velocity: FallingFallBoxVelocity,
  dt: number,
  supported = false,
  armDelaySeconds = FALL_BOX_ARM_DELAY_SECONDS,
  settleStep = FALL_BOX_SETTLE_STEP,
): FallBoxIntegrationResult {
  const stepDt = Number.isFinite(dt) ? Math.max(0, dt) : 0;
  const armedSeconds = velocity.armedSeconds + stepDt;
  if (armedSeconds <= armDelaySeconds) {
    return {
      rect: { ...rect },
      velocity: { y: 0, armedSeconds },
    };
  }

  // Recovered-data: FUN_7ff72bb429b0 waits 0.22s, then applies fixed 0.65px
  // support-settle deltas through FUN_7ff72bb34c40 only while no support exists;
  // support-present frames zero the vertical component at actor+0x11c.
  if (supported) {
    return {
      rect: { ...rect },
      velocity: { y: 0, armedSeconds },
    };
  }

  return {
    rect: { ...rect, y: rect.y + settleStep },
    velocity: { y: settleStep, armedSeconds },
  };
}

export function isFallBoxHorizontallyActiveInNativeView(
  rect: Rect,
  scrollX: number,
  stageScale: number,
): boolean {
  const scale = normalizeNativeScale(stageScale);
  const screenLeft = rect.x - (Number.isFinite(scrollX) ? scrollX : 0);
  const viewWidth = FALL_BOX_NATIVE_SCREEN_WIDTH / scale;
  return !(screenLeft + rect.width + FALL_BOX_OFFSCREEN_MARGIN < 0
    || viewWidth <= screenLeft - FALL_BOX_OFFSCREEN_MARGIN);
}

export function shouldDespawnFallBoxBelowNativeView(rect: Rect, stageScale: number): boolean {
  const scale = normalizeNativeScale(stageScale);
  const actorCenterY = rect.y + rect.height / 2;
  return actorCenterY > (FALL_BOX_NATIVE_SCREEN_HEIGHT / scale) * 2;
}

export function resolveFallBoxPlayerCollision(
  previousPlayerRect: Rect,
  currentPlayerRect: Rect,
  playerVelocity: Vector2,
  fallBoxRects: readonly Rect[],
  fallingBoxIndices: readonly number[] = [],
): FallBoxCollisionResult {
  const falling = new Set(fallingBoxIndices);
  const activeBoxRects: Rect[] = [];
  const triggeredBoxIndices: number[] = [];

  fallBoxRects.forEach((box, index) => {
    if (falling.has(index)) return;
    if (shouldTriggerFallBox(previousPlayerRect, currentPlayerRect, playerVelocity, box)) {
      triggeredBoxIndices.push(index);
      return;
    }
    activeBoxRects.push(box);
  });

  const gateResult = resolveClosedGateCollision(
    previousPlayerRect,
    currentPlayerRect,
    playerVelocity,
    activeBoxRects,
  );

  return {
    playerRect: gateResult.rect,
    playerVelocity: gateResult.velocity,
    grounded: gateResult.grounded,
    blocked: gateResult.blocked,
    triggeredBoxIndices,
  };
}

export function shouldTriggerFallBox(
  previousPlayerRect: Rect,
  currentPlayerRect: Rect,
  playerVelocity: Vector2,
  fallBoxRect: Rect,
): boolean {
  if (playerVelocity.y < 0) return false;

  const horizontalOverlap = Math.min(currentPlayerRect.x + currentPlayerRect.width, fallBoxRect.x + fallBoxRect.width)
    - Math.max(currentPlayerRect.x, fallBoxRect.x);
  if (horizontalOverlap < MIN_HORIZONTAL_OVERLAP) return false;

  const previousBottom = previousPlayerRect.y + previousPlayerRect.height;
  const currentBottom = currentPlayerRect.y + currentPlayerRect.height;
  const crossedTop = previousBottom <= fallBoxRect.y && currentBottom >= fallBoxRect.y && currentPlayerRect.y <= fallBoxRect.y;
  const topContact = rectsOverlap(currentPlayerRect, fallBoxRect)
    && currentBottom >= fallBoxRect.y
    && currentBottom <= fallBoxRect.y + TOP_CONTACT_DEPTH;

  return crossedTop || topContact;
}

function isPositiveFiniteNumber(value: unknown): value is number {
  return typeof value === 'number' && Number.isFinite(value) && value > 0;
}

function normalizeNativeScale(stageScale: number): number {
  return Number.isFinite(stageScale) && stageScale > 0 ? stageScale : 1;
}

function rectsOverlap(a: Rect, b: Rect): boolean {
  return a.x < b.x + b.width
    && a.x + a.width > b.x
    && a.y < b.y + b.height
    && a.y + a.height > b.y;
}
