import { Container, Graphics, Sprite } from 'pixi.js';
import { moveRectWithTileCollisions } from '../physics';
import { TileMap } from '../TileMap';
import type { InputState, Rect, Vector2 } from '../types';
import { drawPicoCat } from '../picoStyle';
import { RECOVERED_AVATAR_VISUAL_ROOT, catTexture, type CatPose } from '../sprites';
import {
  PLAYER_RECT_CENTER_OFFSET_X,
  PLAYER_RECT_CENTER_OFFSET_Y,
  getPlayerRectFromActorCoordinate,
} from './PlayerGeometry';

// Pass-8 ground truth: normal Player motion uses a fixed-tick custom body graph, not the
// separate Box2D MKS bridge. The browser keeps per-second velocities, so native per-tick
// vertical values are multiplied by 60 (speed) or 60^2 (acceleration). Horizontal speed also uses actor units:
// native 3 units/tick becomes 180 px/s.
const MOVE_SPEED = 3 * 60;
// Ordinary directional input directly assigns GetMoveSpeed().
const MOVE_AXIS_SCALE = 1;
const NORMAL_PLAYER_TICKS_PER_SECOND = 60;
// Native jump SET is -5.1 actor units/tick (DAT_7ff72bcbdf90). In the browser's
// per-second representation that is -306; the charge factor scales the SET and held boosts.
const JUMP_SPEED = 5.1 * NORMAL_PLAYER_TICKS_PER_SECOND;
// Variable-height jump (engine-verified state machine, avatar pre-physics slot 25
// FUN_7ff72bb690d0 / per-frame controller FUN_7ff72bb6f0e0, applied once per frame AFTER the
// unsupported-fall correction):
//   press  -> vy = getJumpSpeed(), phase = 1
//   held   -> while phase in 1..13 and the jump button stays down:
//             vy += getJumpSpeed() * (1 - phase/14) * 0.2 ; phase++
//   release/phase 14 -> phase = 0 (boost ends; short-hop)
// The ramp is frame-COUNT based and runs on consecutive normal 1/60 Stage ticks.
const JUMP_HOLD_FRAMES = 13;
const JUMP_HOLD_GAIN = 0.2;
const JUMP_HOLD_DECAY_DEN = 14;
// Native controller timer ctrl+0x1c (`0x3d8f5c29`) resets while grounded and counts down by dt.
const JUMP_COYOTE_SECONDS = 0.07;
// Native unsupported fall adds +0.65 actor units/tick and caps at +19.5/tick
// (FUN_7ff72bb67da0; DAT_7ff72bcb69bc / DAT_7ff72bcbdf88).
const GRAVITY = 0.65 * NORMAL_PLAYER_TICKS_PER_SECOND ** 2;
const MAX_FALL_SPEED = 19.5 * NORMAL_PLAYER_TICKS_PER_SECOND;
// Native normal Stage cadence is fixed at 1/60. Browser frames are clamped by GameRuntime
// to 1/20, so split only normal-Player integration into at-most-native-sized steps. This
// preserves the surrounding runtime body-resolution phase while removing coarse Euler drift.
const NORMAL_PLAYER_MAX_STEP_SECONDS = 1 / 60;
// Browser PlayerGeometry can rest a fraction above (or up to 2px inside) a floor. Probe only
// a thin inset strip under the feet so adjacent side walls do not masquerade as support.
const TILE_SUPPORT_PROBE_DEPTH = 2;
const TILE_SUPPORT_PROBE_INSET = 0.001;
// PlanePlayer speed = 3 units/tick * 1.5 mode-5 multiplier * 60 -> 270 px/s
// (FUN_7ff72bb70860 / FUN_7ff72bb687e0).
const PLANE_MOVE_SPEED = 3 * 1.5 * 60;
// Recovered state-3 fatal-death sequence (pass 8, FUN_7ff72bb6ed30/FUN_7ff72bb6eda0):
// phase 1 holds the avatar for 1.0s (DAT_7ff72bcff538) before play resumes.
export const PLAYER_DEATH_SEQUENCE_SECONDS = 1.0;
export const DEFAULT_PLAYER_BODY_COLOR = 0x66b9ff;
export type PlayerMode = 'normal' | 'plane';

export class Player {
  readonly view = new Container();
  bodyColor: number;
  readonly mode: PlayerMode;
  rect: Rect;
  velocity: Vector2 = { x: 0, y: 0 };
  grounded = false;
  // Jump charge magnitude (engine avatar+0x374). VERIFIED (pass 5) unreachable from the
  // player's own controls: charge is built only by controller action 0x21, emitted solely by
  // a level-spawned charged-launch DEVICE (FUN_7ff72bb5f550), never by the player input scheme.
  // Base/component construction initializes the ordinary multiplier to 1.0
  // (FUN_7ff72bc155e0 -> FUN_7ff72bbaa920, absolute avatar+0x374).
  charge = 1;
  // Native avatar+0x418. BreakoutBall command 0x22 multiplies this value and
  // caps the normal controller at 2.0 (FUN_7ff72bb6fd20).
  moveSpeedMultiplier = 1;
  // Held-jump ramp phase: 0 = not ramping, 1..13 = number of the next held boost frame.
  private jumpPhase = 0;
  private jumpCoyoteTimer = 0;
  // Recovered state-3 death sequence (pass 8): > 0 while the avatar is in the
  // 1.0s fatal-death hold (cmd-4 fatal damage / off-screen fail). The runtime
  // decrements it and skips this player's update while it runs; 0 = alive.
  deathTimer = 0;
  // Real-sprite state (lifted atlas cats; undefined => Graphics fallback).
  private sprite?: Sprite;
  private avatarTrackTime = 0;
  private avatarPose: CatPose = 'default';
  private facing: -1 | 1 = 1;

  constructor(
    actorX: number,
    actorY: number,
    bodyColor = DEFAULT_PLAYER_BODY_COLOR,
    mode: PlayerMode = 'normal',
    private readonly usesMoveSpeedMultiplier = true,
  ) {
    this.bodyColor = bodyColor;
    this.mode = mode;
    this.rect = getPlayerRectFromActorCoordinate(actorX, actorY);
    this.repaint();
    this.syncView();
  }

  // Rebuild the visual: the lifted, palette-baked atlas cat when the sprite
  // atlas is loaded (browser), else the hand-drawn approximation (headless).
  repaint(): void {
    // Optional call: some headless test mocks model Container minimally.
    (this.view as { removeChildren?: () => void }).removeChildren?.();
    const texture = catTexture(this.bodyColor, 'default');
    if (texture) {
      const sprite = new Sprite(texture);
      sprite.anchor.set(0.5, 1);
      // Keep the native visual root separate from the browser collision rect.
      sprite.x = PLAYER_RECT_CENTER_OFFSET_X;
      sprite.y = PLAYER_RECT_CENTER_OFFSET_Y;
      this.sprite = sprite;
      this.view.addChild(sprite);
      this.refreshPose();
    } else {
      this.sprite = undefined;
      const g = new Graphics();
      drawPicoCat(g, this.rect.width, this.rect.height, this.bodyColor);
      this.view.addChild(g);
    }
  }

  setBodyColor(bodyColor: number): void {
    if (this.bodyColor === bodyColor) return;
    this.bodyColor = bodyColor;
    this.repaint();
  }

  getFacingDirection(): -1 | 1 {
    return this.facing;
  }

  applyBreakoutSpeedCommand(payload: number): void {
    this.moveSpeedMultiplier = Math.fround(Math.min(
      Math.fround(this.moveSpeedMultiplier * payload),
      2,
    ));
  }

  // Retain gameplay-facing even when no atlas sprite is available (headless /
  // Graphics fallback), then pick the recovered avatar frame and flip its X.
  refreshPose(advanceAnimationTick = false): void {
    if (this.velocity.x > 0) this.facing = 1;
    else if (this.velocity.x < 0) this.facing = -1;
    if (!this.sprite) return;
    const pose: CatPose = this.deathTimer > 0 ? 'dead'
      : this.mode === 'plane' ? 'plane'
        : !this.grounded ? 'jump'
          : (this.velocity.x !== 0) ? 'walk' : 'default';
    if (pose !== this.avatarPose) {
      this.avatarPose = pose;
      this.avatarTrackTime = 0;
    }
    if (advanceAnimationTick) this.avatarTrackTime += 1;
    const texture = catTexture(this.bodyColor, pose, this.avatarTrackTime);
    if (texture) this.sprite.texture = texture;
    if (texture) {
      this.sprite.scale.set(
        (RECOVERED_AVATAR_VISUAL_ROOT.width / texture.orig.width) * this.facing,
        RECOVERED_AVATAR_VISUAL_ROOT.height / texture.orig.height,
      );
    } else {
      this.sprite.scale.x = Math.abs(this.sprite.scale.x) * this.facing;
    }
  }

  update(dt: number, input: InputState, tileMap: TileMap): void {
    if (this.mode === 'normal' && dt > NORMAL_PLAYER_MAX_STEP_SECONDS) {
      const stepCount = Math.ceil(dt / NORMAL_PLAYER_MAX_STEP_SECONDS);
      const stepDt = dt / stepCount;
      for (let step = 0; step < stepCount; step += 1) {
        this.update(
          stepDt,
          step === 0 ? input : { ...input, jumpPressed: false },
          tileMap,
        );
      }
      return;
    }

    const direction = input.right ? 1 : input.left ? -1 : 0;
    const moveSpeedMultiplier = this.usesMoveSpeedMultiplier
      ? this.moveSpeedMultiplier
      : 1;
    this.velocity.x = direction * MOVE_AXIS_SCALE * MOVE_SPEED * moveSpeedMultiplier;

    if (this.mode === 'plane') {
      this.velocity.x = direction * PLANE_MOVE_SPEED;
      const verticalDirection = input.up ? -1 : input.down ? 1 : 0;
      this.velocity.y = verticalDirection * PLANE_MOVE_SPEED;
      const result = moveRectWithTileCollisions(tileMap, this.rect, {
        x: this.velocity.x * dt,
        y: this.velocity.y * dt,
      });

      this.rect = result.rect;
      if (result.velocity.x === 0) this.velocity.x = 0;
      if (result.velocity.y === 0) this.velocity.y = 0;
      this.grounded = false;
      this.syncView();
      return;
    }

    // Native Player queries recursive support before applying unsupported fall. The browser
    // adapts the tile half of that predicate with a thin foot probe; dynamic bodies continue
    // through GameRuntime's existing downward overlap/resolution path.
    const wasGrounded = this.grounded;
    const hadTileSupport = wasGrounded && tileSupportsPlayer(tileMap, this.rect);
    if (wasGrounded) {
      this.jumpCoyoteTimer = JUMP_COYOTE_SECONDS;
    } else {
      this.jumpCoyoteTimer = Math.max(0, this.jumpCoyoteTimer - dt);
    }
    const canStartJump = wasGrounded || this.jumpCoyoteTimer > 0;
    if (!hadTileSupport) {
      this.velocity.y = Math.min(MAX_FALL_SPEED, this.velocity.y + GRAVITY * dt);
    }

    // Variable-height jump state machine (see JUMP_HOLD_* notes). Native unsupported fall
    // occurs first: a press SET overwrites it, while a held phase adds its boost afterward.
    const startsJump = input.jumpPressed && canStartJump;
    if (startsJump) {
      this.velocity.y = this.getJumpSpeed();
      this.grounded = false;
      this.jumpPhase = 1;
      this.jumpCoyoteTimer = 0;
    } else if (input.jump && this.jumpPhase >= 1 && this.jumpPhase <= JUMP_HOLD_FRAMES) {
      this.velocity.y += this.getJumpSpeed() * (1 - this.jumpPhase / JUMP_HOLD_DECAY_DEN) * JUMP_HOLD_GAIN;
      this.jumpPhase += 1;
    } else {
      this.jumpPhase = 0;
    }

    const result = moveRectWithTileCollisions(tileMap, this.rect, {
      x: this.velocity.x * dt,
      y: this.velocity.y * dt,
    }, wasGrounded);

    this.rect = result.rect;
    if (result.velocity.x === 0) this.velocity.x = 0;
    if (result.velocity.y === 0) this.velocity.y = 0;
    const remainsTileSupported = wasGrounded
      && !startsJump
      && result.velocity.y === 0
      && tileSupportsPlayer(tileMap, result.rect);
    this.grounded = result.grounded || remainsTileSupported;
    if (this.grounded) this.jumpCoyoteTimer = JUMP_COYOTE_SECONDS;
    this.refreshPose(true);
    this.syncView();
  }

  // Engine GetJumpSpeed (FUN_7ff72bb68770): the charge factor pre-scales the base jump.
  // charge>=1 -> native -5.1/tick (-306/s here); explicit charge 0 retains factor 0.8.
  private getJumpSpeed(): number {
    return -JUMP_SPEED * (this.charge < 1 ? this.charge * 0.2 + 0.8 : 1);
  }

  reset(actorX: number, actorY: number): void {
    this.rect = getPlayerRectFromActorCoordinate(actorX, actorY);
    this.velocity = { x: 0, y: 0 };
    this.grounded = false;
    this.jumpPhase = 0;
    this.jumpCoyoteTimer = 0;
    this.deathTimer = 0;
    this.avatarTrackTime = 0;
    this.avatarPose = 'default';
    this.facing = 1;
    this.refreshPose();
    // Respawn reconstructs the ordinary avatar/component with its native multiplier.
    this.charge = 1;
    this.view.scale.set(1);
    this.syncView();
  }

  applyResolvedCollision(rect: Rect, velocity: Vector2, grounded = this.grounded): void {
    this.rect = rect;
    this.velocity = velocity;
    this.grounded = grounded;
    this.syncView();
  }

  private syncView(): void {
    this.view.x = this.rect.x + this.rect.width / 2 - PLAYER_RECT_CENTER_OFFSET_X * this.view.scale.x;
    this.view.y = this.rect.y + this.rect.height + 1 - PLAYER_RECT_CENTER_OFFSET_Y * this.view.scale.y;
  }
}

function tileSupportsPlayer(tileMap: TileMap, rect: Rect): boolean {
  const probe: Rect = {
    x: rect.x + TILE_SUPPORT_PROBE_INSET,
    y: rect.y + rect.height,
    width: Math.max(0, rect.width - TILE_SUPPORT_PROBE_INSET * 2),
    height: TILE_SUPPORT_PROBE_DEPTH,
  };
  return tileMap.rectHitsSolid(probe);
}
