import { Container, Graphics, Sprite, Text, TextStyle } from 'pixi.js';
import { frameTexture } from '../sprites';
import type { ActorSpawnDef, Rect, ValueAtom } from '../types';

// Recovered-data: FUN_7ff72bb3c6f0 installs DAT_7ff72bcb7fc0 as the
// CoopStopWatch panel's local geometry. DAT_7ff72bcb7f90 selects the neutral
// 41x16 atlas frame, which the native 4x draw scale expands to 164x64.
export const COOP_STOP_WATCH_PANEL_LOCAL_RECT = {
  x: -82,
  y: -32,
  width: 164,
  height: 64,
} as const;

export interface CoopStopWatchBounds {
  lower: number;
  upper: number;
}

const COOP_STOP_WATCH_EVENT_EPSILON_SECONDS = 1.1920928955078125e-7;

export class CoopStopWatch {
  readonly view = new Container();
  readonly rect: Rect;
  readonly lowerBound: number;
  readonly upperBound: number;
  panelState: 'neutral' | 'failure' | 'success' = 'neutral';
  currentValueColor = 0xffffff;
  readonly lowerText: Text;
  readonly currentText: Text;
  readonly upperText: Text;
  private readonly neutralPanel: Sprite | Graphics;
  private readonly failurePanel: Sprite | Graphics;
  private readonly successPanel: Sprite | Graphics;

  constructor(readonly spawn: ActorSpawnDef, activePlayerCount: number) {
    const bounds = parseCoopStopWatchBoundsFromSpawn(spawn, activePlayerCount);
    this.lowerBound = bounds.lower;
    this.upperBound = bounds.upper;
    this.rect = {
      x: spawn.x + COOP_STOP_WATCH_PANEL_LOCAL_RECT.x,
      y: spawn.y + COOP_STOP_WATCH_PANEL_LOCAL_RECT.y,
      width: COOP_STOP_WATCH_PANEL_LOCAL_RECT.width,
      height: COOP_STOP_WATCH_PANEL_LOCAL_RECT.height,
    };

    this.view.x = spawn.x;
    this.view.y = spawn.y;
    this.neutralPanel = createNeutralPanel();
    this.failurePanel = createFailurePanel();
    this.successPanel = createSuccessPanel();
    this.failurePanel.visible = false;
    this.successPanel.visible = false;
    this.view.addChild(this.neutralPanel, this.failurePanel, this.successPanel);

    // Recovered-data: FUN_7ff72bb3cac0 draws 32px values at x-100/x/x+100
    // using right/center/left alignment and literal period separators.
    this.lowerText = createValueText(`${formatCoopStopWatchValue(this.lowerBound)} <`, 'right');
    this.lowerText.x = -100;
    this.view.addChild(this.lowerText);

    this.currentText = createValueText(formatCoopStopWatchValue(0, true), 'center');
    this.view.addChild(this.currentText);

    this.upperText = createValueText(`< ${formatCoopStopWatchValue(this.upperBound)}`, 'left');
    this.upperText.x = 100;
    this.view.addChild(this.upperText);
  }

  setPanelState(state: 'neutral' | 'failure' | 'success'): void {
    this.panelState = state;
    this.neutralPanel.visible = state === 'neutral';
    this.failurePanel.visible = state === 'failure';
    this.successPanel.visible = state === 'success';
  }

  publishTimerSnapshot(
    remainingSeconds: readonly number[],
    hasRunningTimerHeartbeat: boolean,
  ): void {
    // Recovered-data: event receiver FUN_7ff72bb3ca20 accumulates each event-0xf
    // payload with float32 additions; POST FUN_7ff72bb3c9e0 publishes that
    // complete collection for the HUD before clearing the transient sum.
    const total = remainingSeconds.reduce(
      (sum, value) => Math.fround(sum + Math.fround(value)),
      0,
    );
    this.currentText.text = formatCoopStopWatchValue(total, true);
    // Recovered-data: HUD draw FUN_7ff72bb3cac0 leaves the prior center-value
    // color untouched while event-0x12 heartbeat bit 1 is present. On a quiet
    // snapshot it selects blue only for the same strict, non-invalid window as
    // FUN_7ff72bb3cf20; epsilon/zero event-0xf values force recovered red.
    if (!hasRunningTimerHeartbeat) {
      const invalid = remainingSeconds.some(
        (value) => Math.abs(Math.fround(value)) <= COOP_STOP_WATCH_EVENT_EPSILON_SECONDS,
      );
      const valid = !invalid && this.lowerBound < total && total < this.upperBound;
      this.currentValueColor = valid ? 0xff1f8f : 0xff8c8c;
      this.currentText.style.fill = this.currentValueColor;
    }
  }
}

export function parseCoopStopWatchBoundsFromSpawn(
  spawn: ActorSpawnDef,
  activePlayerCount: number,
): CoopStopWatchBounds {
  const playerCount = Math.max(1, Math.trunc(activePlayerCount));
  const coordinateIndex = findCoordinatePair(spawn.raw, spawn.x, spawn.y);
  if (coordinateIndex < 0) return { lower: 0, upper: 0 };

  const lower = nativeFloat(spawn.raw[coordinateIndex + 2]);
  const partyParameter = nativeFloat(spawn.raw[coordinateIndex + playerCount + 1]);
  return {
    lower,
    upper: Math.fround(playerCount * partyParameter),
  };
}

export function formatCoopStopWatchValue(value: number, clampWholeSeconds = false): string {
  const floatValue = Number.isFinite(value) ? Math.fround(value) : 0;
  const wholeSeconds = clampWholeSeconds
    ? Math.max(0, Math.min(99, Math.trunc(floatValue)))
    : Math.trunc(floatValue);
  const centiseconds = Math.trunc(Math.fround(floatValue * 100)) % 100;
  return `${padTwo(wholeSeconds)}.${padTwo(centiseconds)}`;
}

function createNeutralPanel(): Sprite | Graphics {
  const texture = frameTexture('coop_stopwatch_neutral');
  if (texture) {
    const sprite = new Sprite(texture);
    sprite.anchor.set(0.5);
    sprite.scale.set(4);
    return sprite;
  }

  // Browser startup loads the exact recovered atlas above. This vector fallback
  // keeps the recovered footprint visible in headless tests or on load failure.
  const panel = new Graphics();
  panel.beginFill(0x101820, 0.9);
  panel.lineStyle(2, 0xffffff, 0.9);
  panel.drawRoundedRect(
    COOP_STOP_WATCH_PANEL_LOCAL_RECT.x,
    COOP_STOP_WATCH_PANEL_LOCAL_RECT.y,
    COOP_STOP_WATCH_PANEL_LOCAL_RECT.width,
    COOP_STOP_WATCH_PANEL_LOCAL_RECT.height,
    8,
  );
  panel.endFill();
  return panel;
}

function createFailurePanel(): Sprite | Graphics {
  const texture = frameTexture('coop_stopwatch_failure');
  if (texture) {
    const sprite = new Sprite(texture);
    sprite.anchor.set(0.5);
    sprite.scale.set(4);
    return sprite;
  }

  // DAT_7ff72bcb7fa0's state-colored pixels are the recovered #ff8c8c.
  const panel = new Graphics();
  panel.beginFill(0xff8c8c, 0.9);
  panel.lineStyle(2, 0xffffff, 0.9);
  panel.drawRoundedRect(
    COOP_STOP_WATCH_PANEL_LOCAL_RECT.x,
    COOP_STOP_WATCH_PANEL_LOCAL_RECT.y,
    COOP_STOP_WATCH_PANEL_LOCAL_RECT.width,
    COOP_STOP_WATCH_PANEL_LOCAL_RECT.height,
    8,
  );
  panel.endFill();
  return panel;
}

function createSuccessPanel(): Sprite | Graphics {
  const texture = frameTexture('coop_stopwatch_success');
  if (texture) {
    const sprite = new Sprite(texture);
    sprite.anchor.set(0.5);
    sprite.scale.set(4);
    return sprite;
  }

  // DAT_7ff72bcb7fb0's recovered atlas pixels use the shipped #5fabf1 blue.
  const panel = new Graphics();
  panel.beginFill(0x5fabf1, 0.9);
  panel.lineStyle(2, 0xffffff, 0.9);
  panel.drawRoundedRect(
    COOP_STOP_WATCH_PANEL_LOCAL_RECT.x,
    COOP_STOP_WATCH_PANEL_LOCAL_RECT.y,
    COOP_STOP_WATCH_PANEL_LOCAL_RECT.width,
    COOP_STOP_WATCH_PANEL_LOCAL_RECT.height,
    8,
  );
  panel.endFill();
  return panel;
}

function createValueText(value: string, alignment: 'left' | 'center' | 'right'): Text {
  const text = new Text(value, new TextStyle({
    fill: 0xffffff,
    fontSize: 32,
    fontFamily: 'monospace',
    fontWeight: '700',
    align: alignment,
    stroke: 0x000000,
    strokeThickness: 4,
  }));
  const anchorX = alignment === 'right' ? 1 : alignment === 'left' ? 0 : 0.5;
  text.anchor.set(anchorX, 0.5);
  return text;
}

function findCoordinatePair(raw: readonly ValueAtom[], x: number, y: number): number {
  for (let index = 0; index < raw.length - 1; index += 1) {
    if (raw[index] === x && raw[index + 1] === y) return index;
  }
  return -1;
}

function nativeFloat(value: ValueAtom | undefined): number {
  return typeof value === 'number' && Number.isFinite(value) ? Math.fround(value) : 0;
}

function padTwo(value: number): string {
  return String(value).padStart(2, '0');
}
