import { Container, Graphics } from 'pixi.js';
import type { ActorSpawnDef, Rect } from '../types';

export class DeadSwitch {
  readonly view = new Container();
  readonly rect: Rect;
  triggered = false;

  constructor(readonly spawn: ActorSpawnDef) {
    this.rect = getDeadSwitchRect(spawn);
    this.view.x = spawn.x;
    this.view.y = spawn.y;

    const g = new Graphics();
    g.beginFill(0x7a1f2b, 0.34);
    g.lineStyle(2, 0xff4f6d, 0.95);
    g.drawRoundedRect(-18, -8, 36, 16, 4);
    g.endFill();
    g.beginFill(0xfff0f3, 0.5);
    g.drawRect(-10, -2, 20, 4);
    g.endFill();
    this.view.addChild(g);
  }

  trigger(): void {
    this.triggered = true;
    this.view.alpha = 0.55;
  }

  release(): void {
    this.triggered = false;
    this.view.alpha = 1;
  }
}

export const DEAD_SWITCH_WIDTH = 36;
export const DEAD_SWITCH_HEIGHT = 16;

export function getDeadSwitchRect(spawn: ActorSpawnDef): Rect {
  return {
    x: spawn.x - DEAD_SWITCH_WIDTH / 2,
    y: spawn.y - DEAD_SWITCH_HEIGHT / 2,
    width: DEAD_SWITCH_WIDTH,
    height: DEAD_SWITCH_HEIGHT,
  };
}

export function shouldRespawnPlayerForDeadSwitch(playerRect: Rect, deadSwitchRect: Rect): boolean {
  return (
    playerRect.x < deadSwitchRect.x + deadSwitchRect.width
    && playerRect.x + playerRect.width > deadSwitchRect.x
    && playerRect.y < deadSwitchRect.y + deadSwitchRect.height
    && playerRect.y + playerRect.height > deadSwitchRect.y
  );
}
