import { Container, Graphics, Sprite } from 'pixi.js';
import type { ActorSpawnDef, Rect, Vector2 } from '../types';
import { frameTexture } from '../sprites';

const KEY_RETURN_GAIN = Math.fround(0.1);
const KEY_RETURN_SNAP_DISTANCE_SQUARED = KEY_RETURN_GAIN;

export class Key {
  readonly view = new Container();
  readonly rect: Rect;
  readonly carryYOffset: number;
  active: boolean;
  collected = false;
  private returningHome = false;

  constructor(readonly spawn: ActorSpawnDef) {
    this.active = !keyStartsHidden(spawn);
    this.carryYOffset = getKeyCarryYOffset(spawn);
    // Recovered-data: FUN_7ff72bb64f20 builds the category-8 sensor from
    // DAT_7ff72bcbdac0 = [-16, -28, 32, 56].
    this.rect = { x: spawn.x - 16, y: spawn.y - 28, width: 32, height: 56 };
    this.view.x = spawn.x;
    this.view.y = spawn.y;

    // Lifted atlas key (key_small, 12x24 native); observed World 1-3 captures
    // show the world key at ~2x the frame size.
    const texture = frameTexture('key_small');
    if (texture) {
      const sprite = new Sprite(texture);
      sprite.anchor.set(0.5);
      sprite.scale.set(2);
      this.view.addChild(sprite);
    } else {
      const g = new Graphics();
      g.beginFill(0xffd34f, 1);
      g.lineStyle(3, 0x6b5200, 1);
      g.drawCircle(-5, 0, 8);
      g.drawRect(2, -2, 18, 4);
      g.drawRect(13, 2, 4, 8);
      g.endFill();
      this.view.addChild(g);
    }

    this.view.visible = this.active;
  }

  activate(): void {
    if (this.collected) return;
    this.active = true;
    this.view.visible = true;
  }

  collect(): void {
    if (!this.active) return;
    this.collected = true;
    this.view.visible = false;
  }

  consume(): void {
    if (!this.active) return;
    // Recovered-data: ordinary Key contact with category-10 KeyGoal puts the
    // native actor in state 2; FUN_7ff72bb65430 then disables its body,
    // detaches its carrier, and advances to consumed state 3.
    this.active = false;
    this.collected = true;
    this.returningHome = false;
    this.view.visible = false;
  }

  // Observed (Steam World 1-3, 2026-07-02): a collected key is CARRIED — it
  // rides beside the collector's head instead of vanishing. Same collected
  // semantics; only the visual differs. The runtime repositions the view.
  carry(): void {
    if (!this.active) return;
    this.collected = true;
    this.view.visible = true;
  }

  releaseFromCarrier(): void {
    if (!this.active) return;
    this.collected = false;
    this.returningHome = true;
    this.syncRectToView();
  }

  advanceReleasedMotion(): void {
    if (!this.returningHome || this.collected) return;

    // Recovered-data: Key PRE FUN_7ff72bb65430 moves state 1 toward the
    // original actor anchor plus param4 Y by delta * DAT_7ff72bc7d464 (0.1f).
    // The same constant is the squared-distance snap threshold; this is a
    // frame-space recurrence, not dt-scaled velocity or gravity.
    const targetX = this.spawn.x;
    const targetY = this.spawn.y + this.carryYOffset;
    if (this.advanceToward(targetX, targetY)) this.returningHome = false;
  }

  advanceCarriedMotion(targetX: number, targetY: number): void {
    if (!this.active || !this.collected) return;

    // Recovered-data: the same FUN_7ff72bb65430 branch runs while +0x408
    // retains a carrier. Follow once per actor frame by float32 delta * 0.1f;
    // do not teleport the presentation or its modeled contact rectangle.
    this.advanceToward(targetX, targetY);
  }

  private advanceToward(targetX: number, targetY: number): boolean {
    const dx = Math.fround(targetX - this.view.x);
    const dy = Math.fround(targetY - this.view.y);
    const distanceSquared = Math.fround(
      Math.fround(dx * dx) + Math.fround(dy * dy),
    );
    if (distanceSquared >= KEY_RETURN_SNAP_DISTANCE_SQUARED) {
      this.view.x = Math.fround(this.view.x + Math.fround(dx * KEY_RETURN_GAIN));
      this.view.y = Math.fround(this.view.y + Math.fround(dy * KEY_RETURN_GAIN));
    } else {
      this.view.x = targetX;
      this.view.y = targetY;
    }
    this.syncRectToView();
    return distanceSquared < KEY_RETURN_SNAP_DISTANCE_SQUARED;
  }

  syncRectToView(): void {
    this.rect.x = this.view.x - this.rect.width / 2;
    this.rect.y = this.view.y - this.rect.height / 2;
  }
}

export class Gate {
  readonly view = new Container();
  readonly rect: Rect;
  opened = false;

  constructor(readonly spawn: ActorSpawnDef) {
    this.rect = { x: spawn.x - 8, y: spawn.y - 32, width: 16, height: 64 };
    this.view.x = spawn.x;
    this.view.y = spawn.y;

    const g = new Graphics();
    g.beginFill(0x4f8cff, 0.9);
    g.lineStyle(3, 0xd7ecff, 1);
    g.drawRoundedRect(-8, -32, 16, 64, 4);
    g.endFill();
    g.lineStyle(2, 0x1c3f7a, 0.9);
    g.moveTo(-4, -26);
    g.lineTo(-4, 26);
    g.moveTo(4, -26);
    g.lineTo(4, 26);
    this.view.addChild(g);
  }

  open(): void {
    this.opened = true;
    this.view.visible = false;
  }

  close(): void {
    this.opened = false;
    this.view.visible = true;
  }
}

export function getKeyTargetActorName(keySpawn: ActorSpawnDef): string | undefined {
  // Recovered raw shapes can be [type, actorName, label, x, y, ...] or
  // [group, subtype, actorName, label, x, y, ...]. Only strings after the
  // x/y coordinate pair are target names; earlier strings are metadata labels.
  const targetStartIndex = findRawTargetStartIndex(keySpawn);
  for (let i = keySpawn.raw.length - 1; i >= targetStartIndex; i--) {
    const value = keySpawn.raw[i];
    if (typeof value !== 'string') continue;
    const trimmed = value.trim();
    if (trimmed.length > 0 && trimmed !== keySpawn.actorName) return trimmed;
  }
  return undefined;
}

export function keyStartsHidden(keySpawn: ActorSpawnDef): boolean {
  const value = keyRawParam(keySpawn, 2);
  return typeof value === 'number' && Number.isFinite(value) && Math.trunc(value) > 0;
}

export function getKeyCarryYOffset(keySpawn: ActorSpawnDef): number {
  const value = keyRawParam(keySpawn, 4);
  return typeof value === 'number' && Number.isFinite(value) ? value : 0;
}

function keyRawParam(keySpawn: ActorSpawnDef, zeroBasedIndex: number): ActorSpawnDef['raw'][number] | undefined {
  return keySpawn.raw[findRawTargetStartIndex(keySpawn) + zeroBasedIndex];
}

function findRawTargetStartIndex(spawn: ActorSpawnDef): number {
  for (let i = 0; i < spawn.raw.length - 1; i++) {
    if (spawn.raw[i] === spawn.x && spawn.raw[i + 1] === spawn.y) return i + 2;
  }
  return 3;
}

export function shouldOpenGateForKey(keySpawn: ActorSpawnDef, gateSpawn: ActorSpawnDef): boolean {
  const targetActorName = getKeyTargetActorName(keySpawn);
  if (!targetActorName) return false;
  if (gateSpawn.actorName === targetActorName) return true;
  return gateSpawn.actorName === 'KeyBridge' && targetActorName === gateSpawn.label;
}

export interface GateCollisionResult {
  rect: Rect;
  velocity: Vector2;
  grounded: boolean;
  blocked: boolean;
}

export function resolveClosedGateCollision(
  previousRect: Rect,
  currentRect: Rect,
  velocity: Vector2,
  closedGateRects: readonly Rect[],
): GateCollisionResult {
  let rect = { ...currentRect };
  const outVelocity = { ...velocity };
  let grounded = false;
  let blocked = false;

  for (const gate of closedGateRects) {
    if (!rectsOverlap(rect, gate)) continue;

    const previousRight = previousRect.x + previousRect.width;
    const previousBottom = previousRect.y + previousRect.height;
    const gateRight = gate.x + gate.width;
    const gateBottom = gate.y + gate.height;

    if (previousRight <= gate.x) {
      rect = { ...rect, x: gate.x - rect.width };
      outVelocity.x = 0;
    } else if (previousRect.x >= gateRight) {
      rect = { ...rect, x: gateRight };
      outVelocity.x = 0;
    } else if (previousBottom <= gate.y) {
      rect = { ...rect, y: gate.y - rect.height };
      outVelocity.y = 0;
      grounded = true;
    } else if (previousRect.y >= gateBottom) {
      rect = { ...rect, y: gateBottom };
      outVelocity.y = 0;
    } else {
      rect = { ...previousRect };
      outVelocity.x = 0;
      outVelocity.y = 0;
    }
    blocked = true;
  }

  return { rect, velocity: outVelocity, grounded, blocked };
}

function rectsOverlap(a: Rect, b: Rect): boolean {
  return a.x < b.x + b.width
    && a.x + a.width > b.x
    && a.y < b.y + b.height
    && a.y + a.height > b.y;
}
