import { Container, Graphics } from 'pixi.js';
import type { ActorSpawnDef, Rect, ValueAtom, Vector2 } from '../types';

export const GHOST_WIDTH = 42;
export const GHOST_HEIGHT = 56;
export const GHOST_LOCAL_X = -21;
export const GHOST_LOCAL_Y = -99;
const GHOST_VISUAL_LOCAL_X = -25;
const GHOST_VISUAL_LOCAL_Y = -100;
const GHOST_VISUAL_WIDTH = 50;
const GHOST_VISUAL_HEIGHT = 58;
const GHOST_CHASE_SOURCE_Y_OFFSET = -50;
const GHOST_DEFAULT_CHASE_SPEED_PER_TICK = Math.fround(1.3);
const GHOST_DEFAULT_KEY_TARGET_RANGE_X = 100;
const GHOST_FADE_STEP_PER_PRE = Math.fround(0.1);
const GHOST_OPACITY_BYTE_MAX = 255;
const GHOST_VISUAL_BOB_AMPLITUDE = Math.fround(8);
const GHOST_VISUAL_BOB_TAU = Math.fround(Math.PI * 2);
const GHOST_VISUAL_BOB_HALF = Math.fround(0.5);

export interface GhostParams {
  gazeRatio: number;
  initialFacing: -1 | 1;
  chaseSpeedPerTick: number;
  keyTargetRangeX: number;
}

export interface GhostPlayerTarget {
  x: number;
  y: number;
  facingPositive: boolean;
}

export interface GhostKeyTarget {
  x: number;
  y: number;
  carried: boolean;
}

export class Ghost {
  readonly view = new Container();
  readonly rect: Rect;
  readonly params: GhostParams;
  velocity: Vector2 = { x: 0, y: 0 };
  gazeCount = 0;
  private readonly visual: Graphics;
  private actorX: number;
  private actorY: number;
  private chasing = false;
  private facing: -1 | 1;
  private keyPickupSensorActive = true;
  private fading = false;
  private fadeTimer = Math.fround(1);
  private visualBobPhase = Math.fround(0);

  constructor(readonly spawn: ActorSpawnDef) {
    this.params = parseGhostParamsFromSpawn(spawn);
    this.actorX = Math.fround(spawn.x);
    this.actorY = Math.fround(spawn.y);
    this.facing = this.params.initialFacing;
    this.rect = getGhostRect(spawn);
    this.view.x = this.actorX;
    this.view.y = this.actorY;

    const g = new Graphics();
    this.visual = g;
    g.beginFill(0xd8d7ff, 0.68);
    g.lineStyle(2, 0xffffff, 0.88);
    g.drawRoundedRect(
      GHOST_VISUAL_LOCAL_X,
      GHOST_VISUAL_LOCAL_Y,
      GHOST_VISUAL_WIDTH,
      GHOST_VISUAL_HEIGHT,
      12,
    );
    g.endFill();
    g.beginFill(0x3b3768, 0.7);
    g.drawRect(-11, -82, 6, 8);
    g.drawRect(5, -82, 6, 8);
    g.endFill();
    this.view.addChild(g);
  }

  // Recovered-data: FUN_7ff72bb51e10 counts eligible Player gaze, applies the
  // stop/restart hysteresis, and writes a direct frame-space chase displacement.
  update(
    players: readonly GhostPlayerTarget[],
    keyTarget?: GhostKeyTarget,
  ): boolean {
    this.velocity.x = 0;
    this.velocity.y = 0;

    let nearest: GhostPlayerTarget | undefined;
    let nearestDistance = Number.POSITIVE_INFINITY;
    let gazeCount = 0;

    for (const player of players) {
      const dx = Math.fround(Math.fround(player.x) - this.actorX);
      const dy = Math.fround(Math.fround(player.y) - this.actorY);
      const distance = float32Length(dx, dy);
      if (distance < nearestDistance) {
        nearest = player;
        nearestDistance = distance;
      }
      if (
        (dx < 0 && player.facingPositive)
        || (dx >= 0 && !player.facingPositive)
      ) {
        gazeCount += 1;
      }
    }

    this.gazeCount = gazeCount;
    const quorum = Math.max(
      1,
      Math.trunc(Math.fround(Math.fround(players.length) * this.params.gazeRatio)),
    );
    if (!this.chasing) {
      if (gazeCount === 0) this.chasing = true;
    } else if (gazeCount >= quorum) {
      this.chasing = false;
    }

    // Recovered-data: Key state 2 sends command 0x18 through
    // FUN_7ff72bb65430, latching Ghost bit 0x4 in FUN_7ff72bb51db0.
    // FUN_7ff72bb51e10 then subtracts float32 0.1 once per active PRE,
    // quantizes the nonnegative timer to an opacity byte, and removes the
    // offline actor when the tenth subtraction becomes slightly negative.
    if (this.fading) {
      this.fadeTimer = Math.fround(this.fadeTimer - GHOST_FADE_STEP_PER_PRE);
      if (this.fadeTimer < 0) return false;
      const clampedTimer = Math.min(1, Math.max(0, this.fadeTimer));
      const opacityByte = Math.trunc(
        Math.fround(Math.fround(clampedTimer) * GHOST_OPACITY_BYTE_MAX),
      );
      this.view.alpha = opacityByte / GHOST_OPACITY_BYTE_MAX;
      return true;
    }

    if (!this.chasing) return true;

    if (nearest) {
      const selectedTarget = keyTarget
        && !keyTarget.carried
        && Math.abs(Math.fround(Math.fround(keyTarget.x) - this.actorX)) < this.params.keyTargetRangeX
        ? keyTarget
        : nearest;
      const dx = Math.fround(Math.fround(selectedTarget.x) - this.actorX);
      const sourceY = Math.fround(this.actorY + GHOST_CHASE_SOURCE_Y_OFFSET);
      const dy = Math.fround(Math.fround(selectedTarget.y) - sourceY);
      const distance = float32Length(dx, dy);
      if (distance !== 0) {
        const step = Math.fround(Math.min(this.params.chaseSpeedPerTick, distance));
        this.velocity.x = Math.fround(Math.fround(dx / distance) * step);
        this.velocity.y = Math.fround(Math.fround(dy / distance) * step);
        this.actorX = Math.fround(this.actorX + this.velocity.x);
        this.actorY = Math.fround(this.actorY + this.velocity.y);
        if (this.velocity.x < 0) this.facing = -1;
        else if (this.velocity.x > 0) this.facing = 1;
        this.syncPosition();
      }
    }

    // Recovered-data: the active-chase tail of FUN_7ff72bb51e10 disables
    // category-9 body 0 once the named ordinary Key has any carrier. Key
    // capture occurs in the later contact pass, so this first happens on a
    // subsequent active-chase PRE and is not re-enabled in normal play.
    if (keyTarget?.carried) this.keyPickupSensorActive = false;
    return true;
  }

  // Recovered-data: Ghost POST slot FUN_7ff72bb52360 advances a float32 phase,
  // writes sin(phase * 2) * 8 to the presentation offset at actor+0x138, and
  // wraps the stored phase after the sampled doubled phase reaches 2*pi.
  // Native body sync FUN_7ff72bc17ca0 reads the actor anchor instead, so this
  // must move only the visual child and never the root view or contact rect.
  updatePost(dt: number): void {
    const frameSeconds = Math.fround(dt);
    this.visualBobPhase = Math.fround(frameSeconds + this.visualBobPhase);
    const doubledPhase = Math.fround(this.visualBobPhase + this.visualBobPhase);
    const sineAsFloat = Math.fround(Math.sin(doubledPhase));
    const visualY = Math.fround(sineAsFloat * GHOST_VISUAL_BOB_AMPLITUDE);

    if (doubledPhase >= GHOST_VISUAL_BOB_TAU) {
      this.visualBobPhase = Math.fround(
        Math.fround(doubledPhase - GHOST_VISUAL_BOB_TAU) * GHOST_VISUAL_BOB_HALF,
      );
    }
    this.visual.y = visualY;
  }

  receiveCommand18(): void {
    this.fading = true;
  }

  isChasing(): boolean {
    return this.chasing;
  }

  getFacingDirection(): -1 | 1 {
    return this.facing;
  }

  getActorAnchor(): Vector2 {
    return { x: this.actorX, y: this.actorY };
  }

  isKeyPickupSensorActive(): boolean {
    return this.keyPickupSensorActive;
  }

  private syncPosition(): void {
    this.view.x = this.actorX;
    this.view.y = this.actorY;
    this.rect.x = Math.fround(this.actorX + GHOST_LOCAL_X);
    this.rect.y = Math.fround(this.actorY + GHOST_LOCAL_Y);
  }
}

export function getGhostRect(spawn: ActorSpawnDef): Rect {
  return {
    x: Math.fround(spawn.x + GHOST_LOCAL_X),
    y: Math.fround(spawn.y + GHOST_LOCAL_Y),
    width: GHOST_WIDTH,
    height: GHOST_HEIGHT,
  };
}

export function shouldRespawnPlayerForGhost(playerRect: Rect, ghostRect: Rect): boolean {
  return (
    playerRect.x < ghostRect.x + ghostRect.width
    && playerRect.x + playerRect.width > ghostRect.x
    && playerRect.y < ghostRect.y + ghostRect.height
    && playerRect.y + playerRect.height > ghostRect.y
  );
}

export function parseGhostParamsFromSpawn(spawn: ActorSpawnDef): GhostParams {
  const params = ghostParamsAfterCoordinatePair(spawn);
  const ratio = params[0];
  const initialLeft = params[1];
  const speed = params[2];
  const keyRange = params[3];
  const initialLeftValue = finiteFloat32(initialLeft);

  return {
    // FUN_7ff72bb51ce0 always overwrites ctor +0x3f8 from p0. A missing or
    // non-numeric entry therefore becomes zero rather than retaining 0.5f.
    gazeRatio: finiteFloat32(ratio) ?? 0,
    initialFacing: initialLeftValue !== undefined
      && Math.trunc(initialLeftValue) > 0
      ? -1
      : 1,
    // p2/p3 retain ctor defaults only when absent. Present non-number entries
    // are native tag mismatches and overwrite the corresponding field with 0.
    chaseSpeedPerTick: params.length > 2
      ? finiteFloat32(speed) ?? 0
      : GHOST_DEFAULT_CHASE_SPEED_PER_TICK,
    keyTargetRangeX: params.length > 3
      ? finiteFloat32(keyRange) ?? 0
      : GHOST_DEFAULT_KEY_TARGET_RANGE_X,
  };
}

function ghostParamsAfterCoordinatePair(spawn: ActorSpawnDef): readonly ValueAtom[] {
  const actorNameIndex = spawn.raw.findIndex((value) => value === 'Ghost');
  const firstCoordinateIndex = actorNameIndex >= 0 ? actorNameIndex + 2 : 0;

  for (let index = firstCoordinateIndex; index <= spawn.raw.length - 2; index += 1) {
    if (spawn.raw[index] === spawn.x && spawn.raw[index + 1] === spawn.y) {
      return spawn.raw.slice(index + 2);
    }
  }

  return [];
}

function finiteFloat32(value: ValueAtom | undefined): number | undefined {
  return typeof value === 'number' && Number.isFinite(value)
    ? Math.fround(value)
    : undefined;
}

function float32Length(x: number, y: number): number {
  return Math.fround(Math.sqrt(Math.fround(
    Math.fround(x * x) + Math.fround(y * y),
  )));
}
