import type { TileMap } from '../TileMap';
import type { Rect } from '../types';
import {
  BreakoutBall,
  type BreakoutBallMapContact,
} from './BreakoutBall';

const BATTLE_BREAKOUT_BALL_TINT_FACTOR = 0.7;
const NATIVE_PLAYER_PALETTE = [
  0x7fbfff,
  0xff8c8c,
  0xffff8c,
  0xa8ffa8,
  0xffb782,
  0xffa8ff,
  0xcf9fff,
  0xe0e0e0,
  0xcfb79f,
  0xffffff,
] as const;

export class BattleBreakoutBall extends BreakoutBall {
  lastTouchOwnerKey = -1;
  resultFinalized = false;

  constructor(centerX: number, centerY: number) {
    super(centerX, centerY);
  }

  override update(
    dt: number,
    tileMap: TileMap,
    onMapContact?: (contact: BreakoutBallMapContact) => void,
    onNativeTickStart?: () => void,
  ): BreakoutBallMapContact[] {
    if (this.resultFinalized) return [];
    return super.update(dt, tileMap, onMapContact, onNativeTickStart);
  }

  tryApplyOwnedPlayerContact(
    previousPlayerRect: Rect,
    currentPlayerRect: Rect,
    ownerKey: number,
  ): boolean {
    if (this.resultFinalized) return false;
    if (!this.tryApplyPlayerContact(previousPlayerRect, currentPlayerRect)) return false;
    if (
      Number.isInteger(ownerKey)
      && ownerKey >= 0
      && ownerKey < NATIVE_PLAYER_PALETTE.length
    ) {
      this.lastTouchOwnerKey = ownerKey;
      // Offline GameControls starts as identity; ownerKey is already the live
      // binding written at Player+0x400 and indexes DAT_7ff72c62a040 here.
      this.setBodyTint(darkenNativePlayerColor(NATIVE_PLAYER_PALETTE[ownerKey]));
    }
    return true;
  }

  receiveJudgeFinalization(): void {
    // Base Judge command 9 broadcasts command 0x1c before building the result
    // ledger. FUN_7ff72bb39c70 marks this specialized ball inactive, and the
    // actor manager then skips its later PRE/POST motion and cell publication.
    this.resultFinalized = true;
  }

  override applyBreakoutSpeedCommand(_payload: number): void {
    // PTR_FUN_7ff72bcb76a0 routes Stage commands through FUN_7ff72bb39c70,
    // which handles only command 0x1c and never forwards base command 0x22.
  }

  override tryStartLossFromMapContact(
    _contact: BreakoutBallMapContact,
    _tileMap: TileMap,
  ): boolean {
    // FUN_7ff72bb39ac0 writes ball+0x404 = 0, disabling the inherited
    // downward-map 180-tick loss entry for this specialized family.
    return false;
  }
}

function darkenNativePlayerColor(color: number): number {
  const scaleChannel = (shift: number): number => (
    Math.min(
      255,
      Math.max(
        0,
        Math.trunc(Math.fround(
          Math.fround((color >>> shift) & 0xff)
          * Math.fround(BATTLE_BREAKOUT_BALL_TINT_FACTOR),
        )),
      ),
    )
  );
  return (
    (scaleChannel(16) << 16)
    | (scaleChannel(8) << 8)
    | scaleChannel(0)
  );
}
