import { Container, Graphics } from 'pixi.js';
import type { ActorSpawnDef, Rect, ValueAtom } from '../types';

export interface PlaneObstacleParams {
  shape: string;
  variant: number;
  span: number;
  numericFlags: number[];
}


export class PlaneObstacle {
  readonly view = new Container();
  readonly params?: PlaneObstacleParams;
  readonly rect: Rect;

  constructor(readonly spawn: ActorSpawnDef) {
    this.params = parsePlaneObstacleParamsFromSpawn(spawn);
    this.view.x = spawn.x;
    this.view.y = spawn.y;

    const width = Math.max(24, Math.abs(this.params?.span ?? 96));
    const height = 24;
    this.rect = {
      x: spawn.x - width / 2,
      y: spawn.y - height / 2,
      width,
      height,
    };
    // Recovered-data: FUN_7ff72bb3e590 and FUN_7ff72bb3e730 publish the
    // PlaneObstacle collision children through descriptors named "PushBox".
    // Reuse that family's established browser presentation instead of the old
    // unevidenced per-shape cyan/amber debug palette.
    const g = new Graphics();
    g.beginFill(0xffffff, 1);
    g.lineStyle(3, 0xff7f45, 1);
    g.drawRoundedRect(-width / 2, -height / 2, width, height, 5);
    g.endFill();
    this.view.addChild(g);
  }
}

export function parsePlaneObstacleParamsFromSpawn(spawn: ActorSpawnDef): PlaneObstacleParams | undefined {
  return parsePlaneObstacleParamsAfterCoordinatePair(spawn.raw, spawn.x, spawn.y);
}

export function parsePlaneObstacleParamsAfterCoordinatePair(
  raw: readonly ValueAtom[],
  x: number,
  y: number,
): PlaneObstacleParams | undefined {
  for (let index = 0; index <= raw.length - 5; index++) {
    if (raw[index] !== x || raw[index + 1] !== y) continue;

    const shape = raw[index + 2];
    const variant = raw[index + 3];
    const span = raw[index + 4];
    if (typeof shape !== 'string' || shape.length === 0) continue;
    if (!isFiniteNumber(variant) || !isFiniteNumber(span)) continue;

    return {
      shape,
      variant,
      span,
      numericFlags: raw.slice(index + 5).filter(isFiniteNumber),
    };
  }

  return undefined;
}

function isFiniteNumber(value: ValueAtom | undefined): value is number {
  return typeof value === 'number' && Number.isFinite(value);
}
