import { Container, Graphics, Sprite } from 'pixi.js';
import type { Rect } from '../types';
import { frameTexture } from '../sprites';

export class Goal {
  readonly view = new Container();
  readonly rect: Rect;
  opened = false;
  private doorSprite?: Sprite;

  open(): void {
    this.opened = true;
    const texture = frameTexture('door_black');
    if (texture && this.doorSprite) this.doorSprite.texture = texture;
  }

  constructor(x: number, y: number) {
    // Trigger footprint unchanged (goal-clear attribution depends on it); only the
    // visual is corrected below.
    this.rect = { x: x - 24, y: y - 32, width: 48, height: 32 };
    this.view.x = x;
    this.view.y = y;

    // The lifted atlas goal doorway (door_black, 48x48 native) — the same black
    // mound Robert's Steam World 1-2 capture identified, now the real pixels.
    // Observed (World 1-3 captures 2026-07-02): the doorway spans ~2 chips, so
    // the 48px frame renders at 2x (96x96), anchored to the floor line.
    const texture = frameTexture('door_closed');
    if (texture) {
      const sprite = new Sprite(texture);
      sprite.anchor.set(0.5, 1);
      sprite.width = 64; sprite.height = 64;
      sprite.y = 0; // flush with the trigger rect's floor line
      this.view.addChild(sprite);
      this.doorSprite = sprite;
      return;
    }

    // Observed PICO PARK goal (Steam World 1-2 capture, 2026-06-24): a solid BLACK
    // mound with a rounded top, sitting flush on the floor — no orange door frame,
    // no interior cutout, no button on top.
    const g = new Graphics();
    g.lineStyle(0);
    g.beginFill(0x000000, 1);
    g.drawRoundedRect(-20, -30, 40, 60, 12);
    g.endFill();
    // Square off the bottom corners so the mound sits flat on the floor (rounded top only).
    g.beginFill(0x000000, 1);
    g.drawRect(-20, -18, 40, 48);
    g.endFill();
    this.view.addChild(g);
  }
}
