export const IMPLEMENTED_RUNTIME_ACTOR_NAMES = Object.keys(
  IMPLEMENTED_RUNTIME_ACTOR_REGISTRY,
) as ImplementedRuntimeActorName[];
function selectRuntimeActorNames(
  predicate: (actorName: ImplementedRuntimeActorName) => boolean,
): ImplementedRuntimeActorName[] {
  return IMPLEMENTED_RUNTIME_ACTOR_NAMES.filter(predicate);
}

export const RUNTIME_PLAYER_ACTOR_NAMES = selectRuntimeActorNames((actorName) => {
  const registryEntry = IMPLEMENTED_RUNTIME_ACTOR_REGISTRY[actorName];
  return 'runtimeRole' in registryEntry && registryEntry.runtimeRole === 'player';
});
