export interface GameRuntimeLoadOptions {
  simplifyPassivePlaceholders?: boolean;
  // Party size (2-8). When set, only the first N Player rows are spawned and the
  // count-variant map is chosen for N. Undefined = spawn every recovered Player
  // row (the original behaviour), so existing callers/tests are unaffected.
  partySize?: number;
}

export interface GameRuntimeEvent {
  // 'hit' = recovered cmd-4 damage cue (DAT_7ff72bcbddd0 "hit" sound string);
  // 'dead' keeps firing at the respawn boundary, matching the recovered
  // hit -> state-3 hold -> return-to-play sequence.
  type: 'jump' | 'coin' | 'get' | 'clear' | 'switch' | 'warp' | 'dead' | 'hit';
  playerIndex: number;
}

