function deadTimerSwitchTargets(switchSpawn: ActorSpawnDef): string[] {
  const explicitLabel = switchSpawn.label.trim();
  const targets: string[] = [];
  const rawTargets: string[] = [];
  let hasQualifiedRawDeadTimerTarget = false;

  const rawTargetStartIndex = findRawTargetStartIndex(switchSpawn);
  for (let index = rawTargetStartIndex; index < switchSpawn.raw.length; index += 1) {
    const value = switchSpawn.raw[index];
    if (typeof value !== 'string') continue;
    const target = value.trim();
    if (!target) continue;
    if (isQualifiedDeadTimerTarget(target)) hasQualifiedRawDeadTimerTarget = true;
    rawTargets.push(target);
  }

  if (!(isBareDeadTimerTarget(explicitLabel) && hasQualifiedRawDeadTimerTarget)) {
    targets.push(explicitLabel);
  }
  targets.push(...rawTargets);

  return targets.filter(Boolean);
}

function isBareDeadTimerTarget(target: string): boolean {
  return /^DeadTimer$/i.test(target.trim());
}

function isQualifiedDeadTimerTarget(target: string): boolean {
  return /^DeadTimer.+$/i.test(target.trim());
}

