function shouldOpenTrafficLightForSwitch(switchSpawn: ActorSpawnDef, trafficLightSpawn: ActorSpawnDef): boolean {
  const trafficLightLabel = trafficLightSpawn.label.trim();
  if (!trafficLightLabel) return false;

  const targetLabels = new Set<string>();
  const explicitLabel = switchSpawn.label.trim();
  if (explicitLabel) targetLabels.add(explicitLabel);

  const rawTargetStartIndex = findRawTargetStartIndex(switchSpawn);
  for (let index = rawTargetStartIndex; index < switchSpawn.raw.length; index += 1) {
    const value = switchSpawn.raw[index];
    if (typeof value !== 'string') continue;
    const label = value.trim();
    if (label) targetLabels.add(label);
  }

  for (const target of targetLabels) {
    if (target === trafficLightLabel) return true;
    const lightTarget = /^TrafficLight(.+)$/i.exec(target);
    if (lightTarget !== null && lightTarget[1] === trafficLightLabel) return true;
  }
  return false;
}

function shouldActivateBaseLiftForSwitch(switchSpawn: ActorSpawnDef, liftSpawn: ActorSpawnDef): boolean {
  if (liftSpawn.actorName !== 'Lift') return false;
  const liftLabel = liftSpawn.label.trim();
  if (!liftLabel) return false;

  return switchActivationTargetLabels(switchSpawn).some((target) => {
    const liftTarget = /^Lift(.+)$/i.exec(target);
    return liftTarget !== null && liftTarget[1].trim() === liftLabel;
  });
}

function switchActivationTargetLabels(switchSpawn: ActorSpawnDef): string[] {
  const labels = new Set<string>();
  const explicitLabel = switchSpawn.label.trim();
  if (explicitLabel) labels.add(explicitLabel);

  const rawTargetStartIndex = findRawTargetStartIndex(switchSpawn);
  for (let index = rawTargetStartIndex; index < switchSpawn.raw.length; index += 1) {
    const value = switchSpawn.raw[index];
    if (typeof value !== 'string') continue;
    const label = value.trim();
    if (label) labels.add(label);
  }

  return [...labels];
}

function switchTargetsSwitchMediator(switchSpawn: ActorSpawnDef, switchMediatorSpawn: ActorSpawnDef): boolean {
  if (switchMediatorSpawn.actorName !== 'SwitchMediator') return false;
  const mediatorLabels = switchMediatorLabels(switchMediatorSpawn);
  return switchMediatorTargets(switchSpawn).some((target) => mediatorLabels.includes(target));
}

function switchMediatorTargets(switchSpawn: ActorSpawnDef): string[] {
  const targets = new Set<string>();
  const explicitLabel = switchSpawn.label.trim();
  const rawTargets = new Set<string>();
  let hasQualifiedRawSwitchMediatorTarget = false;

  const rawTargetStartIndex = findRawTargetStartIndex(switchSpawn);
  for (let index = rawTargetStartIndex; index < switchSpawn.raw.length; index += 1) {
    const value = switchSpawn.raw[index];
    if (typeof value !== 'string') continue;
    const rawLabel = value.trim();
    if (isQualifiedSwitchMediatorTarget(rawLabel)) hasQualifiedRawSwitchMediatorTarget = true;
    const label = normalizeSwitchMediatorTarget(rawLabel);
    const rawTargetsAnotherMediator = (
      switchSpawn.actorName !== 'SwitchMediator'
      || isBareSwitchMediatorTarget(rawLabel)
      || isQualifiedSwitchMediatorTarget(rawLabel)
    );
    if (label && rawTargetsAnotherMediator) rawTargets.add(label);
  }

  if (
    explicitLabel
    && !(rawTargets.size > 0 && (isBareSwitchMediatorTarget(explicitLabel) || hasQualifiedRawSwitchMediatorTarget))
  ) {
    const label = normalizeSwitchMediatorTarget(explicitLabel);
    if (label) targets.add(label);
  }
  for (const rawTarget of rawTargets) targets.add(rawTarget);

  return [...targets];
}

function normalizeSwitchMediatorTarget(target: string): string {
  const mediatorTarget = /^SwitchMediator(.+)$/i.exec(target);
  return (mediatorTarget?.[1] ?? target).trim();
}

function isBareSwitchMediatorTarget(target: string): boolean {
  return /^SwitchMediator$/i.test(target.trim());
}

function isQualifiedSwitchMediatorTarget(target: string): boolean {
  return /^SwitchMediator.+$/i.test(target.trim());
}

function switchMediatorLabels(switchMediatorSpawn: ActorSpawnDef): string[] {
  const labels = new Set<string>();
  const explicitLabel = switchMediatorSpawn.label.trim();
  if (explicitLabel) labels.add(explicitLabel);

  const rawTargetStartIndex = findRawTargetStartIndex(switchMediatorSpawn);
  for (let index = rawTargetStartIndex; index < switchMediatorSpawn.raw.length; index += 1) {
    const value = switchMediatorSpawn.raw[index];
    if (typeof value !== 'string') continue;
    const label = value.trim();
    if (label) labels.add(label);
  }

  return [...labels];
}

function findRawTargetStartIndex(spawn: ActorSpawnDef): number {
  for (let index = 0; index < spawn.raw.length - 1; index += 1) {
    if (spawn.raw[index] === spawn.x && spawn.raw[index + 1] === spawn.y) return index + 2;
  }
  return 6;
}

function endlessLaserBallPitcherTargetsEndlessJumpScore(spawn: ActorSpawnDef): boolean {
  if (spawn.actorName !== 'EndlessLaserBallPitcher') return false;
  const targetStartIndex = findRawTargetStartIndex(spawn);
  const targetName = spawn.raw[targetStartIndex + 2];
  return typeof targetName === 'string' && targetName.trim() === 'EndlessJumpScore';
}

