function rectsOverlap(a: Rect, b: Rect): boolean {
  return a.x < b.x + b.width
    && a.x + a.width > b.x
    && a.y < b.y + b.height
    && a.y + a.height > b.y;
}

function rectsTouchOrOverlap(a: Rect, b: Rect, epsilon = 0): boolean {
  return a.x <= b.x + b.width + epsilon
    && a.x + a.width >= b.x - epsilon
    && a.y <= b.y + b.height + epsilon
    && a.y + a.height >= b.y - epsilon;
}

function rectContactNormalY(source: Rect, other: Rect, previousOther: Rect): -1 | 0 | 1 {
  const previousRight = previousOther.x + previousOther.width;
  const previousBottom = previousOther.y + previousOther.height;
  const sourceRight = source.x + source.width;
  const sourceBottom = source.y + source.height;
  if (previousRight <= source.x || previousOther.x >= sourceRight) return 0;
  if (previousBottom <= source.y) return -1;
  if (previousOther.y >= sourceBottom) return 1;

  // If the lift itself created contact, the Player's previous rectangle can
  // already overlap the lift's new position. Match the solver with a
  // minimum-translation fallback for that moving-body case.
  const overlaps = {
    down: sourceBottom - other.y,
    up: other.y + other.height - source.y,
    right: sourceRight - other.x,
    left: other.x + other.width - source.x,
  };
  const shallowest = Math.min(overlaps.down, overlaps.up, overlaps.right, overlaps.left);
  if (overlaps.down <= shallowest + Number.EPSILON) return 1;
  if (overlaps.up <= shallowest + Number.EPSILON) return -1;
  return 0;
}

function rectRestsOnSupport(rect: Rect, support: Rect): boolean {
  return Math.abs(rect.y + rect.height - support.y) <= 0.5
    && rect.x + rect.width > support.x
    && rect.x < support.x + support.width;
}

function rectCenter(rect: Rect): { x: number; y: number } {
  return {
    x: rect.x + rect.width / 2,
    y: rect.y + rect.height / 2,
  };
}

