import { Container, Graphics } from 'pixi.js';
import type { ActorSpawnDef } from '../types';

export interface PhysicsSwitchParams {
  targetLabel: string;
}

export class PhysicsSwitch {
  readonly view = new Container();
  readonly params: PhysicsSwitchParams;

  constructor(readonly spawn: ActorSpawnDef) {
    this.params = parsePhysicsSwitchParamsFromSpawn(spawn);
    this.view.x = spawn.x;
    this.view.y = spawn.y;

    const g = new Graphics();
    g.beginFill(0x38bdf8, 0.28);
    g.lineStyle(2, 0x7dd3fc, 0.9);
    g.drawRoundedRect(-17, -7, 34, 14, 4);
    g.endFill();
    g.beginFill(0xffffff, 0.55);
    g.drawCircle(-6, 0, 3);
    g.drawCircle(6, 0, 3);
    g.endFill();
    this.view.addChild(g);
  }
}

export function parsePhysicsSwitchParamsFromSpawn(spawn: ActorSpawnDef): PhysicsSwitchParams {
  return {
    targetLabel: spawn.label,
  };
}
