import { Container, Graphics, Sprite } from 'pixi.js';
import type { Rect } from '../types';
import { frameTexture } from '../sprites';

export class Coin {
  readonly view = new Container();
  readonly rect: Rect;
  collected = false;

  constructor(x: number, y: number) {
    this.rect = { x: x - 12, y: y - 12, width: 24, height: 24 };
    this.view.x = x;
    this.view.y = y;

    // Lifted atlas coin (12x20 native) when sprites are loaded.
    const texture = frameTexture('coin_0');
    if (texture) {
      const sprite = new Sprite(texture);
      sprite.anchor.set(0.5);
      sprite.scale.set(20 / texture.orig.height);
      this.view.addChild(sprite);
      return;
    }

    const g = new Graphics();
    // Round gold disc with a darker rim, matching coin.png / contact_sheet.png.
    g.lineStyle(3, 0x6b5200, 1);
    g.beginFill(0xffd34f, 1);
    g.drawCircle(0, 0, 11);
    g.endFill();
    // Lighter vertical highlight so it reads as a coin face. (drawRect, not
    // drawEllipse: the shared Graphics test mock only implements rect/circle.)
    g.lineStyle(0);
    g.beginFill(0xfff0a8, 0.6);
    g.drawRect(-3.5, -7, 3, 14);
    g.endFill();
    this.view.addChild(g);
  }

  collect(): void {
    this.collected = true;
    this.view.visible = false;
  }
}
