import { Container, Graphics } from 'pixi.js';
import type { ActorSpawnDef, Rect, ValueAtom } from '../types';

export const DEFAULT_STATIC_RECT_SIZE = 32;

export interface StaticRectDimensions {
  width: number;
  height: number;
}

export class StaticRect {
  readonly view = new Container();
  readonly rect: Rect;

  constructor(readonly spawn: ActorSpawnDef, nativeBody?: Rect) {
    this.rect = nativeBody ?? getStaticRectRect(spawn);

    // Observed (Steam World 1-3 captures 2026-07-02): native Rect blockers are
    // indistinguishable from map platforms — flat #ff864d with rounded corners
    // (jump02's stair-step blocks are these). The old gray debug fill made
    // whole levels read wrong.
    const g = new Graphics();
    const radius = Math.round(Math.min(this.rect.width, this.rect.height) * 0.28);
    g.lineStyle(0, 0, 0);
    g.beginFill(0xff864d, 1);
    g.drawRoundedRect(0, 0, this.rect.width, this.rect.height, radius);
    g.endFill();
    this.view.addChild(g);
    this.view.x = this.rect.x;
    this.view.y = this.rect.y;
  }
}

export function getStaticRectDimensions(spawn: ActorSpawnDef): StaticRectDimensions {
  const { width, height } = findDimensionsAfterCoordinatePair(spawn.raw, spawn.x, spawn.y);
  return {
    width: nonZeroFiniteAbsOrDefault(width, DEFAULT_STATIC_RECT_SIZE),
    height: nonZeroFiniteAbsOrDefault(height, DEFAULT_STATIC_RECT_SIZE),
  };
}

function findDimensionsAfterCoordinatePair(
  raw: readonly ValueAtom[],
  x: number,
  y: number,
): { width: ValueAtom | undefined; height: ValueAtom | undefined } {
  for (let index = 0; index <= raw.length - 2; index++) {
    if (raw[index] !== x || raw[index + 1] !== y) continue;
    return { width: raw[index + 2], height: raw[index + 3] };
  }

  return { width: undefined, height: undefined };
}

export function getStaticRectRect(spawn: ActorSpawnDef): Rect {
  const { width, height } = getStaticRectDimensions(spawn);
  return {
    x: spawn.x - width / 2,
    y: spawn.y - height / 2,
    width,
    height,
  };
}

function nonZeroFiniteAbsOrDefault(value: unknown, fallback: number): number {
  if (typeof value !== 'number' || !Number.isFinite(value) || value === 0) {
    return fallback;
  }

  return Math.abs(value);
}
